import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSelector, createSlice } from "@reduxjs/toolkit";
import { nanoid } from "nanoid";

export type ReferenceModel = {
  id: string;
  parentId: string;
  label: string;
  url: string;
};

const adapter = createEntityAdapter<ReferenceModel, string>({
  selectId: (reference) => reference.id,
});

const slice = createSlice({
  name: "entities/references",
  initialState: adapter.getInitialState(),
  reducers: {
    addReference: adapter.addOne,
    updateReference: adapter.updateOne,
    removeReference: adapter.removeOne,
    removeReferences: adapter.removeMany,
    removeAllReferences: adapter.removeAll,
    setReferences: adapter.setAll,
    upsertReference: adapter.upsertOne,
    upsertReferences: adapter.upsertMany,
    addReferences: adapter.addMany,
    updateReferences: adapter.updateMany,
  },
});

export const referencesReducer = slice.reducer;
export const ReferencesActions = slice.actions;
const selectors = adapter.getSelectors<CommonState>((state) => state.entities.references);
const selectReferencesByParentId = createSelector(
  [selectors.selectAll, (state, id: string) => id],
  (references, id) => {
    return references.filter((reference) => reference.parentId === id);
  }
);
export const ReferencesSelectors = { ...selectors, selectReferencesByParentId };

//
export const createNewReference = (parentId: string) => {
  const id = nanoid();
  return {
    id,
    parentId,
    label: "",
    url: "",
  };
};
