import { isValidString } from "@core/utils/isValidString";
import { useAppDispatch } from "@viewer/state/hooks";
import { CurrentViewerDocumentActions } from "@viewer/state/slices/currentDocumentSlice";

export const useInitialDocument = (props: {
  dataUrl: string;
  taxIds: string[];
  variantId: string;
}) => {
  const dispatch = useAppDispatch();
  const urlParams = getUrlParams();

  if (isValidString(props.dataUrl) || isValidString(urlParams.dataUrl)) {
    if (isValidString(props.dataUrl)) {
      dispatch(CurrentViewerDocumentActions.setSpecificDataUrl(props.dataUrl));
      return;
    }
    if (isValidString(urlParams.dataUrl)) {
      dispatch(CurrentViewerDocumentActions.setSpecificDataUrl(urlParams.dataUrl));
      return;
    }
  } else {
    dispatch(CurrentViewerDocumentActions.setSpecificDataUrl(""));
  }

  if (props.taxIds.length > 0 && props.variantId.length > 0) {
    dispatch(CurrentViewerDocumentActions.setTaxIds(props.taxIds));
    dispatch(CurrentViewerDocumentActions.setVariantId(props.variantId));
    return;
  }
  if (isValidString(urlParams.taxIds) && isValidString(urlParams.variantId)) {
    dispatch(CurrentViewerDocumentActions.setTaxIds(urlParams.taxIds.split(",")));
    dispatch(CurrentViewerDocumentActions.setVariantId(urlParams.variantId));
    return;
  }
};

const getUrlParams = () => {
  const urlParams = new URLSearchParams(window.location.search);
  const taxIds = urlParams.get("taxon") ?? "";
  const variantId = urlParams.get("pathway") ?? "";
  const dataUrl = urlParams.get("dataURL") ?? "";
  return { dataUrl, taxIds, variantId };
};
