import { ClippableText } from "@core/canvas/atoms/ClippableText";
import { Triangle } from "@core/canvas/atoms/Triangle";
import { SelectionRect } from "@core/canvas/elements/SelectionRect";
import { findCircumCircleCenter } from "@core/canvas/utils/findCircumCircleCenter";
import { findTriangleVertices } from "@core/canvas/utils/findTriangleVertices";
import { useTooltip } from "@core/state/hooks/useToolTip";
import { NodeElementProps } from "@core/types";
import React, { FC, useMemo } from "react";

type Placement = "bottom" | "right";
type Props = NodeElementProps & { placement: Placement };
const REACTION_HEIGHT = 5;
const TRIANGLE_ANGLE = 60;

export const ReactionElement: FC<Props> = ({
  x,
  y,
  label,
  clickFn,
  isSelected,
  placement,
  fillColor,
  strokeColor,
  strokeWidth,
  labelWidth,
}) => {
  const direction = useMemo(() => (placement === "right" ? -90 : 0), [placement]);
  const center = useMemo(() => {
    const vert1 = { x, y };
    const [vert2, vert3] = findTriangleVertices(vert1, REACTION_HEIGHT, TRIANGLE_ANGLE, direction);
    return findCircumCircleCenter(vert1, vert2, vert3);
  }, [x, y, direction]);
  const labelPos = useMemo(() => {
    switch (placement) {
      case "bottom":
        return { x: x, y: y + REACTION_HEIGHT * 1.4 + 6 };
      case "right":
        return { x: x + REACTION_HEIGHT * 1.4 + 5, y: y - 5 };
    }
  }, [x, y, placement]);
  const labelAnchor = useMemo(() => {
    switch (placement) {
      case "bottom":
        return "center";
      case "right":
        return "left";
    }
  }, [placement]);

  const { setTooltipValue } = useTooltip();
  const onMouseOver = () => {
    setTooltipValue(label || "");
  };
  const onMouseOut = () => {
    setTooltipValue("");
  };

  return (
    <g
      onMouseOut={onMouseOut}
      onMouseOver={onMouseOver}
      onClick={clickFn}
      style={clickFn && { cursor: "pointer", pointerEvents: "auto" }}
    >
      <Triangle
        x={x}
        y={y}
        height={REACTION_HEIGHT}
        angle={TRIANGLE_ANGLE}
        direction={direction}
        fillColor={fillColor ? fillColor : "#000000"}
        strokeColor={strokeColor ? strokeColor : "#FFFFFF"}
        strokeWidth={strokeWidth || strokeWidth === 0 ? strokeWidth : 0}
      />

      {label && (
        <ClippableText
          x={labelPos.x}
          y={labelPos.y}
          label={label}
          textAlign={labelAnchor}
          width={labelWidth}
        ></ClippableText>
      )}
      <SelectionRect
        x={center.x}
        y={center.y}
        width={(center.r * 2) / 1.4}
        height={(center.r * 2) / 1.4}
        isVisible={isSelected}
      />
    </g>
  );
};
