import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { TagSelectionActions } from "@core/state/slices/app/selection/tagSelection";
import { LayoutTagModel } from "@core/state/slices/entities/layoutTagModelSlice";
import { selectLayoutTagValuesByTagId } from "@core/state/slices/entities/layoutTagValueModelSlice";
import List from "@mui/material/List";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import { LayoutListItem } from "@viewer/propertyPanel/sub/LayoutListItem";
import React, { FC } from "react";

type Props = {
  tag: LayoutTagModel;
};

export const LayoutList: FC<Props> = ({ tag }) => {
  const values = useAppSelector((state) => selectLayoutTagValuesByTagId(state, tag.id));

  const dispatch = useAppDispatch();
  const onClickListItem = (valueId: string) => {
    dispatch(
      TagSelectionActions.mergeTagSelection({
        valueId,
        isMultiple: tag.selectionType === "multiple",
      })
    );
  };

  return (
    <Stack data-testid={`layoutList:${tag.id}`}>
      <Typography>{tag.label}</Typography>
      <List>
        {values.map((value) => (
          <LayoutListItem
            value={value}
            key={value.id}
            onClick={onClickListItem}
          />
        ))}
      </List>
    </Stack>
  );
};
