import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import {
  ModalActions,
  selectCurrentModalId,
  selectIsModalOpen,
} from "@core/state/slices/app/modal";

export const useModal = () => {
  const dispatch = useAppDispatch();
  const openModal = (modalType: string) => {
    dispatch(ModalActions.openModal(modalType));
  };
  const closeModal = () => {
    dispatch(ModalActions.closeModal());
  };
  const isModalOpen = useAppSelector(selectIsModalOpen);
  const currentModalId = useAppSelector(selectCurrentModalId);

  return { openModal, closeModal, isModalOpen, currentModalId };
};
