import { AppProvider } from "@core/AppProvider";
import { PathwayViewer } from "@viewer/PathwayViewer";
import { store } from "@viewer/state/store";
import type { ComponentProps, FC } from "react";

export type ViewerAppProps = ComponentProps<typeof PathwayViewer>;

// 単体起動と組み込みで共用する入口。DOMへのマウントは利用側が行う。
export const ViewerApp: FC<ViewerAppProps> = (props) => (
  <AppProvider store={store}>
    <PathwayViewer {...props} />
  </AppProvider>
);
