import { ClippableText } from "@core/canvas/atoms/ClippableText";
import { useAppSelector } from "@core/state/hooks";
import { selectLayoutTags } from "@core/state/selectors/selectLayoutTags";
import { selectSelectedNodeModel } from "@core/state/selectors/selectSelectedNodeModel";
import { selectGridSize } from "@core/state/slices/app/gridSlice";
import { type FC, ReactNode, useLayoutEffect, useRef, useState } from "react";
type Props = {
  children: ReactNode;
  layoutId: string;
  // onMeasure: (layoutId: string, height: number) => void;
  x: number;
  y: number;
};

export const PathwayFrame: FC<Props> = ({ children, layoutId, x, y }) => {
  const padding = 20;
  const gridSize = useAppSelector(selectGridSize);
  const groupRef = useRef<SVGGElement>(null);
  const [bounds, setBounds] = useState<DOMRect | null>(null);
  useLayoutEffect(() => {
    if (groupRef.current) {
      const bbox = groupRef.current.getBBox();
      setBounds(bbox);
    }
  }, [children, gridSize]);

  const rectX = bounds ? bounds.x - padding : 0;
  const rectY = bounds ? bounds.y - padding : 0;
  const rectWidth = bounds ? bounds.width + padding * 2 : 0;
  const rectHeight = bounds ? bounds.height + padding * 2 - padding * 0.5 : 0;

  const label = useLayoutTitle(layoutId);
  const isSelected = false;
  const COLOR_SELECTED = "#00f";
  const onClickDocumentTitle = () => {};

  return (
    <g
      data-pathway-frame={layoutId}
      transform={`translate(${x}, ${y})`}
      style={{ transitionDuration: "0.2s", transitionProperty: "transform" }}
    >
      <g>
        <g>
          <rect
            x={rectX}
            y={rectY}
            width={rectWidth}
            height={rectHeight}
            fill="transparent"
            {...(!isSelected
              ? { stroke: "#000", strokeDasharray: 3, strokeWidth: 1 }
              : { stroke: COLOR_SELECTED, strokeWidth: 2 })}
          />
        </g>
        {label.length && (
          <ClippableText
            x={rectX - 1}
            y={rectY - 24}
            height={24}
            fontSize={14}
            width={rectWidth}
            label={label}
            textAlign="left"
            color="#FFF"
            backgroundColor="#000"
            padding="5px"
            onClick={onClickDocumentTitle}
          />
        )}
      </g>
      <g ref={groupRef}>{children}</g>
    </g>
  );
};

const useLayoutTitle = (layoutId: string): string => {
  const tags = useAppSelector((state) => selectLayoutTags(state, layoutId));
  const taxon = tags.find(({ tag }) => tag?.id === "taxonomy")?.value?.label ?? "No taxon info";
  const rest = tags
    .filter(
      ({ tag, value }) => tag?.id !== "taxonomy" && tag?.selectionType === "multiple" && !!value
    )
    .map(({ value }) => `[${value?.label}]`);
  return rest.join(",");
};
