import { Paper, PaperProps } from "@mui/material";
import { grey } from "@mui/material/colors";
import { FC } from "react";

type Props = {} & PaperProps;

export const Sheet: FC<Props> = ({ children, square = true, sx, ...rest }) => {
  const _sx: PaperProps["sx"] = [
    ...(Array.isArray(sx) ? sx : sx ? [sx] : []),
    { boxShadow: 0, color: grey[200] },
  ];
  return (
    <Paper
      sx={_sx}
      square={square}
      {...rest}
    >
      {children}
    </Paper>
  );
};
