import { Sheet } from "@core/components/mui/Sheet";
import { useProteinPanel } from "@viewer/hooks/useProteinPanel";
import { AndProteinPane } from "@viewer/propertyPanel/pane/AndProteinPane";
import { OrProteinPane } from "@viewer/propertyPanel/pane/OrProteinPane";
import { SimpleProteinPane } from "@viewer/propertyPanel/pane/SimpleProteinPane";
import React, { FC } from "react";

type Props = { id: string; parentId?: string };

export const ProteinPane: FC<Props> = ({ id, parentId }) => {
  const { protein } = useProteinPanel(id);
  const hasAllOf: boolean = (protein?.allOf?.length ?? 0) > 0;
  const hasOneOf: boolean = (protein?.oneOf?.length ?? 0) > 0;
  const isSimple = !hasOneOf && !hasAllOf;

  if (!protein) return <></>;

  return (
    <Sheet sx={{ maxHeight: "max-content", px: parentId ? 0 : 2, py: parentId ? 1 : 2 }}>
      {isSimple && (
        <SimpleProteinPane
          id={id}
          parentId={parentId}
        />
      )}
      {hasOneOf && <OrProteinPane id={id} />}
      {hasAllOf && <AndProteinPane id={id} />}
    </Sheet>
  );
};
