import { selectSelectedItemType } from "@core/state/selectors/selectSelectedItemType";
import Box from "@mui/material/Box";
import Stack from "@mui/material/Stack";
import { styled } from "@mui/material/styles";
import { DocumentPanel } from "@viewer/propertyPanel/panels/DocumentPanel";
import { GeneralPanel } from "@viewer/propertyPanel/panels/GeneralPanel";
import { NodePanel } from "@viewer/propertyPanel/panels/NodePanel";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import { selectIsPropertyPanelOpen, ViewerPanelActions } from "@viewer/state/slices/panelSlice";
import React, { FC } from "react";

type Props = {};

export const PropertyPanel: FC<Props> = ({}) => {
  const { isDrawerOpen, onClickToggleButton } = useDrawerStatus();
  const selectedType = useAppSelector(selectSelectedItemType);

  return (
    <Wrapper
      className={isDrawerOpen ? "open" : "closed"}
      data-testid="propertyPanel"
    >
      {selectedType === "none" && <GeneralPanel />}
      {selectedType === "document" && <DocumentPanel />}
      {selectedType === "node" && <NodePanel />}
      <ToggleButton
        onClick={onClickToggleButton}
        data-testid="propertyPanelToggle"
      >
        <span className={"inner"}>Properties</span>
      </ToggleButton>
    </Wrapper>
  );
};

const useDrawerStatus = () => {
  const isDrawerOpen = useAppSelector(selectIsPropertyPanelOpen);
  const dispatch = useAppDispatch();
  const onClickToggleButton = () => {
    dispatch(ViewerPanelActions.togglePropertyPanel());
  };
  return { isDrawerOpen, onClickToggleButton };
};

const Wrapper = styled(Stack)(({ theme }) => ({
  width: 360,
  height: "100%",
  position: "absolute",
  top: 0,
  right: 0,
  gap: "0.5rem",
  boxSizing: "border-box",
  background: theme.palette.background.default,
  transitionDuration: "0.3s",
  transitionProperty: "transform",
  transitionTimingFunction: "ease-in-out",
  ["&.closed"]: {
    transform: "translateX(100%)",
  },
  ["&.open"]: {
    transform: "translateX(0)",
  },
}));
const ToggleButton = styled(Box)(({ theme }) => ({
  position: "absolute",
  top: 0,
  left: -24,
  width: 24,
  height: "85px",
  background: theme.palette.background.default,
  borderColor: theme.palette.divider,
  borderStyle: "solid",
  borderWidth: "1px",
  userSelect: "none",
  cursor: "pointer",
  ["& .inner"]: {
    position: "absolute",
    top: 5,
    left: 2,
    fontSize: "15px",
    transform: "translateY(-100%) rotate(90deg)",
    transformOrigin: "bottom left",
    color: theme.palette.text.primary,
  },
}));
