import { ErrorLogActions } from "@core/state/slices/errorLogSlice";
import { clearData } from "@core/state/utils/clearData";
import { importData } from "@core/state/utils/import";
import { AppData } from "@schema/app/AppData";
import { useQueries } from "@tanstack/react-query";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import { selectDataUrls } from "@viewer/state/slices/currentDocumentSlice";
import { ViewerPanelActions } from "@viewer/state/slices/panelSlice";
import { useEffect } from "react";

const usePathwayQueries = () => {
  const urls = useAppSelector(selectDataUrls);
  const dispatch = useAppDispatch();
  useEffect(() => {
    dispatch(clearData());
  }, [urls, dispatch]);
  const { data, isPending, isSuccess } = useQueries({
    queries: urls.map((url) => ({
      queryKey: [url],
      queryFn: async () => {
        const res = await fetch(url);
        const contentType = res.headers.get("content-type");
        if (!contentType || !contentType.includes("application/json")) {
          // window.alert("Loading error: Expected JSON but received non-JSON response");
          const text = await res.text();
          dispatch(ErrorLogActions.addError("Expected JSON but received non-JSON response"));
          console.error("Non-JSON response:", res);
          console.error(text);
          throw new Error("Expected JSON but received non-JSON response");
        }
        const data: AppData = await res.json();
        return { data, res };
      },
      staleTime: Infinity,
    })),
    combine: (results) => {
      const data = results.map((result) => result?.data?.data || null).filter(Boolean) as AppData[];
      const isPending = results.some((result) => result.isPending);
      const isSuccess = results.every((result) => result.isSuccess);
      const isError = results.some((result) => result.isError);
      if (isError) {
        // window.alert("something went wrong with loading process, please check");
        console.error(results);
      }
      return {
        data,
        isPending,
        isSuccess,
      };
    },
  });

  return { data, isPending, isSuccess };
};

export const useLoadPathways = () => {
  const { data, isSuccess } = usePathwayQueries();
  const dispatch = useAppDispatch();
  useEffect(() => {
    if (isSuccess && data.length > 0) {
      data.forEach((pathwayData, i) => pathwayData && dispatch(importData(pathwayData, i !== 0)));
      dispatch(ViewerPanelActions.closeBrowserPanel());
      dispatch(ViewerPanelActions.openPropertyPanel());
      //
      // const url = new URL(window.location.href);
      // url.searchParams.set("pathway", variantId);
      // url.searchParams.set("taxon", taxIds.join(","));
      // window.history.replaceState({}, "", url.toString());
    }
  }, [data, isSuccess, dispatch]);
};
