import { getX, getY } from "@core/canvas/utils/setPosition";
import { CanvasMode } from "@core/state/slices/app/canvasModeSlice";
import { NodeModel } from "@core/state/slices/entities/nodeModelsSlice";
import { NodeElementProps } from "@core/types";

export type NodeObjProps = { model: NodeModel; mode?: CanvasMode; grid: number };
export const composeNodeElementProps = (
  node: NodeModel,
  grid: number,
  label: string,
  isSelected: boolean,
  clickFn: () => void
): NodeElementProps => {
  return {
    label,
    x: getX(node.x, grid, 0),
    y: getY(node.y, grid, 0),
    clickFn,
    isSelected,
    fillColor: node.fillColor,
    strokeColor: node.strokeColor,
    strokeWidth: node.strokeWidth,
    strokeStyle: node.strokeStyle,
  };
};
