import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSlice } from "@reduxjs/toolkit";
import { DocumentData } from "@schema/app/AppData";

export type DocumentModel = Omit<DocumentData, "references"> & { visible: boolean };
export type DocumentLabel = null | keyof Omit<DocumentModel, "id" | "description" | "synonym">;

const adapter = createEntityAdapter<DocumentModel, string>({
  selectId: (document) => document.id,
  sortComparer: (a, b) => (a.taxId ?? "").localeCompare(b.taxId ?? ""),
});

const slice = createSlice({
  name: "entities/documents",
  initialState: adapter.getInitialState(),
  reducers: {
    addDocument: adapter.addOne,
    updateDocument: adapter.updateOne,
    upsertDocument: adapter.upsertOne,
    removeDocument: adapter.removeOne,
    addDocuments: adapter.addMany,
    updateDocuments: adapter.updateMany,
    upsertDocuments: adapter.upsertMany,
    removeDocuments: adapter.removeMany,
    setDocuments: adapter.setAll,
    removeAllDocuments: adapter.removeAll,
  },
});

export const documentsReducer = slice.reducer;
export const DocumentsActions = slice.actions;
export const DocumentsSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.documents
);
