import { ConnectionElement } from "@core/canvas/elements/ConnectionElement";
import { makeConnectionProps } from "@core/canvas/utils/makeConnectionProps";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { useIsItemSelected } from "@core/state/hooks/useIsItemSelected";
import { selectCanvasMode } from "@core/state/slices/app/canvasModeSlice";
import { selectGridSize } from "@core/state/slices/app/gridSlice";
import { ItemSelectionActions } from "@core/state/slices/app/selection/itemSelection";
import { ConnectionModel } from "@core/state/slices/entities/connectionModelsSlice";
import { NodesSelectors } from "@core/state/slices/entities/nodeModelsSlice";
import React, { FC } from "react";

type Props = {
  model: ConnectionModel;
};

export const ConnectionObject: FC<Props> = ({ model }) => {
  const dispatch = useAppDispatch();
  const canvasMode = useAppSelector(selectCanvasMode);
  const onSelect = () => {
    dispatch(ItemSelectionActions.setSelectedItemId(model.id));
  };
  const clickFn = canvasMode === "edit" ? onSelect : undefined;
  const source = useAppSelector((state) => NodesSelectors.selectById(state, model.source));
  const target = useAppSelector((state) => NodesSelectors.selectById(state, model.target));
  const isSelected = useIsItemSelected(model.id);
  const grid = useAppSelector(selectGridSize);
  if (!source || !target) return <></>;
  return (
    <ConnectionElement
      {...makeConnectionProps(model, isSelected, source, target, grid)}
      clickFn={clickFn}
    />
  );
};
