import { extendZod } from "@schema/extendZod";
import z from "zod";
import { referenceDataSchema } from "./ReferenceData";

extendZod();

export type ProteinData = {
  id: string;
  name?: string;
  synonym?: string;
  reactionId: string;
  geneName?: string;
  organism?: string;
  taxId?: string;
  description?: string;
  references?: z.infer<typeof referenceDataSchema>[];
  oneOf?: ProteinData[];
  allOf?: ProteinData[];
};

// Recursive wrapper (breaks the cycle)
export const proteinDataSchema: z.ZodType<ProteinData> = z.lazy(() => ProteinDataObject);

// Concrete object schema (where we attach the OpenAPI name)
const ProteinDataObject: z.ZodType<ProteinData> = z
  .object({
    id: z.string(),
    name: z.string().optional(),
    synonym: z.string().optional(),
    reactionId: z.string(),
    geneName: z.string().optional(),
    organism: z.string().optional(),
    taxId: z.string().optional(),
    description: z.string().optional(),
    references: z.array(referenceDataSchema).optional(),
    oneOf: z.array(proteinDataSchema).optional(),
    allOf: z.array(proteinDataSchema).optional(),
  })
  .openapi("ProteinData");
