import type { ImportValidationResult } from "@core/state/utils/validateImportJson";
import { Alert, TextField } from "@mui/material";
import Button from "@mui/material/Button";
import Dialog from "@mui/material/Dialog";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import Stack from "@mui/material/Stack";
import React, { FC, FormEventHandler, useState } from "react";

type Props = {
  open: boolean;
  onClose: () => void;
  onSubmit: (json: string) => void;
  onValidate?: (json: string) => ImportValidationResult;
};

export const ImportDialog: FC<Props> = ({ open, onClose, onSubmit, onValidate }) => (
  <Dialog
    open={open}
    onClose={onClose}
    fullWidth={true}
  >
    <DialogTitle>Import Data</DialogTitle>
    <DialogContent>
      <ImportForm
        onSubmit={onSubmit}
        onValidate={onValidate}
      />
    </DialogContent>
  </Dialog>
);

// Dialogが閉じて内容がアンマウントされると入力と検証結果も破棄される。
const ImportForm: FC<Pick<Props, "onSubmit" | "onValidate">> = ({ onSubmit, onValidate }) => {
  const [json, setJson] = useState("");
  const [result, setResult] = useState<ImportValidationResult | null>(null);
  const handleSubmit: FormEventHandler<HTMLFormElement> = (e) => {
    e.preventDefault();
    if (onValidate) {
      const issues = onValidate(json);
      setResult(issues);
      if (issues.errors.length > 0) return;
    }
    if (json !== "") onSubmit(json);
  };

  return (
    <form onSubmit={handleSubmit}>
      <Stack sx={{ gap: 1 }}>
        <TextField
          id="outlined-textarea"
          placeholder={"Paste JSON Data here"}
          label="JSON data"
          value={json}
          onChange={(event) => {
            setJson(event.target.value);
          }}
          multiline
          name={"json"}
          minRows={10}
          maxRows={10}
        />
        {result !== null && result.errors.length === 0 && result.warnings.length === 0 && (
          <Alert
            severity="success"
            role="status"
          >
            Validation passed. Ready to import.
          </Alert>
        )}
        {result !== null && result.errors.length > 0 && (
          <Alert
            severity="error"
            sx={{ overflowWrap: "anywhere" }}
          >
            Validation failed.
            <ul style={{ margin: 0, paddingLeft: "1.5rem" }}>
              {result.errors.map((error, index) => (
                <li key={index}>{error}</li>
              ))}
            </ul>
          </Alert>
        )}
        {result !== null && result.warnings.length > 0 && (
          <Alert
            severity="warning"
            sx={{ overflowWrap: "anywhere" }}
          >
            Undefined fields will be removed during import.
            <ul style={{ margin: 0, paddingLeft: "1.5rem" }}>
              {result.warnings.map((warning, index) => (
                <li key={index}>{warning}</li>
              ))}
            </ul>
          </Alert>
        )}
        <Stack
          direction="row"
          spacing={1}
        >
          {onValidate && (
            <Button
              type="button"
              variant="outlined"
              fullWidth
              onClick={() => setResult(onValidate(json))}
            >
              Validate
            </Button>
          )}
          <Button
            type={"submit"}
            variant={"contained"}
            fullWidth
          >
            Submit
          </Button>
        </Stack>
      </Stack>
    </form>
  );
};
