import { RouteConfig } from "@asteasolutions/zod-to-openapi";
import { compoundDataSchema } from "@schema/app/CompoundData";
import { layoutDataSchema } from "@schema/app/LayoutData";
import { layoutTagDataSchema } from "@schema/app/LayoutTagData";
import { proteinDataSchema } from "@schema/app/ProtainData";
import { reactionDataSchema } from "@schema/app/ReactionData";
import { referenceDataSchema } from "@schema/app/ReferenceData";
import { currentVer } from "@schema/const";
import { z } from "zod";

const documentSchema = z.object({
  id: z.string(),
  title: z.string(),
  taxId: z.string(),
  description: z.string().optional(),
  organism: z.string().optional(),
  references: z.array(referenceDataSchema).optional(),
});
export type DocumentData = z.infer<typeof documentSchema>;

export const appDataSchema = z.object({
  meta: z.object({
    ver: z.literal(currentVer),
  }),
  document: documentSchema,
  layoutTags: z.array(layoutTagDataSchema).openapi({
    example: [
      {
        id: "mode",
        label: "Mode",
        selection: "single",
        values: [
          { key: "compound-only", label: "Compound Only" },
          { key: "reaction", label: "Reaction" },
          { key: "protein", label: "Protein" },
        ],
      },
      {
        id: "prediction",
        label: "Prediction Status",
        selection: "single",
        values: [
          { key: "predicted", label: "Predicted" },
          { key: "curated", label: "Curated" },
        ],
      },
    ],
  }),
  layouts: z.array(layoutDataSchema),
  entities: z.object({
    proteins: z.array(proteinDataSchema),
    reactions: z.array(reactionDataSchema),
    compounds: z.array(compoundDataSchema),
  }),
});
export type AppData = z.infer<typeof appDataSchema>;
export const appDataJsonSchema = z.toJSONSchema(appDataSchema);

export const appDataRequestDoc: RouteConfig = {
  path: "/pathway",
  method: "get",
  summary: "pathway json",
  request: {},
  responses: {
    200: {
      description: "",
      content: {
        "application/json": {
          schema: appDataSchema,
        },
      },
    },
  },
};
