import createCache from "@emotion/cache";
import { CacheProvider } from "@emotion/react";
import React, { FC, PropsWithChildren, useEffect, useRef, useState } from "react";
import { EmotionGlobalStyles } from "./EmotionGlobalStyles";

export type EmotionCacheProviderProps = {} & PropsWithChildren;

export const EmotionCacheProvider: FC<EmotionCacheProviderProps> = ({ children }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const createMyCache = () =>
    createCache({
      key: "stanza",
      container: containerRef.current as HTMLElement,
    });
  // TODO: 子の再マウントとShadow DOMへのCSS挿入を検証し、DOM確定後のcache初期化へ見直す。
  // oxlint-disable-next-line react/refs -- 初回cacheを作り、DOM確定後に挿入先を切り替える既存手順を維持する。
  const [myCache, setMyCache] = useState(createMyCache);
  // oxlint-disable-next-line react/set-state-in-effect -- mount後にcontainer用cacheへ切り替える既存手順を維持する。
  useEffect(() => setMyCache(createMyCache), []);
  return (
    <CacheProvider value={myCache}>
      <EmotionGlobalStyles />
      <div
        style={{ display: "contents" }}
        ref={containerRef}
      >
        {children}
      </div>
    </CacheProvider>
  );
};
