import { ScrollWrapper } from "@core/components/atoms/ScrollWrapper";
import { Sheet } from "@core/components/mui/Sheet";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { LabelKeyActions, selectDocumentLabelKey } from "@core/state/slices/app/labelKeySlice";
import { selectSelectedItemId } from "@core/state/slices/app/selection/itemSelection";
import { DocumentLabel, DocumentsSelectors } from "@core/state/slices/entities/documentModelsSlice";
import { Tab, Tabs } from "@mui/material";
import Box from "@mui/material/Box";
import { FieldSet } from "@viewer/propertyPanel/sub/FieldSet";
import { ReferenceList } from "@viewer/propertyPanel/sub/ReferenceList";
import React, { FC } from "react";

type Props = {};

export const DocumentPanel: FC<Props> = ({}) => {
  const dispatch = useAppDispatch();
  const currentSelectionId = useAppSelector(selectSelectedItemId) ?? "";
  const currentDocument = useAppSelector((state) =>
    DocumentsSelectors.selectById(state, currentSelectionId)
  );
  const currentLabel = useAppSelector(selectDocumentLabelKey);

  const onCheckLabel = (value: DocumentLabel) => {
    const next = currentLabel === value ? null : value;
    dispatch(LabelKeyActions.setDocumentLabelKey(next));
  };

  if (!currentDocument) return <></>;

  return (
    <Box sx={{ height: "100%", overflow: "hidden", display: "flex", flexDirection: "column" }}>
      <Tabs value={0}>
        <Tab
          label={"Document"}
          value={0}
        />
      </Tabs>

      <ScrollWrapper>
        <Sheet
          sx={{ maxHeight: "max-content", p: 2, display: "flex", flexDirection: "column", gap: 2 }}
        >
          <FieldSet
            title={"Title"}
            checkBoxProps={{
              checked: currentLabel === "title",
              onClick: () => onCheckLabel("title"),
            }}
          >
            {currentDocument.title}
          </FieldSet>
          <FieldSet title={"Description"}>{currentDocument.description}</FieldSet>
          <FieldSet
            title={"Organism"}
            checkBoxProps={{
              checked: currentLabel === "organism",
              onClick: () => onCheckLabel("organism"),
            }}
          >
            {currentDocument.organism}
          </FieldSet>
          <FieldSet
            title={"Tax id"}
            checkBoxProps={{
              checked: currentLabel === "taxId",
              onClick: () => onCheckLabel("taxId"),
            }}
          >
            {currentDocument.taxId}
          </FieldSet>
          <ReferenceList parentId={currentDocument.id} />
        </Sheet>
      </ScrollWrapper>
    </Box>
  );
};
