import { ViewerApp } from "@viewer/embed";
import React, { FC } from "react";

type Props = {
  taxIds?: string[];
  variantId?: string;
  dataUrl?: string;
  gridSize?: number;
  height?: number;
};

export const App: FC<Props> = ({ taxIds = [], variantId = "", dataUrl = "", gridSize, height }) => {
  return (
    <React.StrictMode>
      <ViewerApp
        documentBrowser={false}
        taxIds={taxIds}
        variantId={variantId}
        dataUrl={dataUrl}
        gridSize={gridSize}
        height={height}
      />
    </React.StrictMode>
  );
};
