import { Circle } from "@core/canvas/atoms/Circle";
import { ClippableText } from "@core/canvas/atoms/ClippableText";
import { SelectionRect } from "@core/canvas/elements/SelectionRect";
import { useTooltip } from "@core/state/hooks/useToolTip";
import { NodeElementProps } from "@core/types";
import React, { FC } from "react";

//
export const COMPOUND_RADIUS = 6;
export const SUB_COMPOUND_RADIUS = 4;
type Props = NodeElementProps & { sub?: boolean };
export type CompoundNodeData = Props;

export const CompoundElement: FC<Props> = ({
  x,
  y,
  label,
  clickFn,
  isSelected,
  sub = false,
  fillColor,
  strokeColor,
  strokeWidth,
  labelWidth,
}) => {
  const radius = sub ? SUB_COMPOUND_RADIUS : COMPOUND_RADIUS;
  const { setTooltipValue } = useTooltip();

  const onMouseOver = () => {
    setTooltipValue(label || "");
  };
  const onMouseOut = () => {
    setTooltipValue("");
  };
  return (
    <g
      onMouseOut={onMouseOut}
      onMouseOver={onMouseOver}
      onClick={clickFn}
      style={
        clickFn && {
          cursor: "pointer",
          pointerEvents: "auto",
        }
      }
    >
      <Circle
        radius={radius}
        x={x}
        y={y}
        fillColor={fillColor ? fillColor : "#ffffff"}
        strokeColor={strokeColor ? strokeColor : "#000000"}
        strokeWidth={strokeWidth || strokeWidth === 0 ? strokeWidth : 1.5}
      />
      {label && (
        <ClippableText
          x={x}
          y={y + radius + (sub ? 4 : 6)}
          label={label}
          width={labelWidth}
        ></ClippableText>
      )}
      <SelectionRect
        x={x}
        y={y}
        width={radius * 2}
        height={radius * 2}
        isVisible={isSelected}
      />
    </g>
  );
};
