import { referenceDataSchema } from "@schema/app/ReferenceData";
import { extendZod } from "@schema/extendZod";
import z from "zod";

extendZod();

export const compoundDataSchema = z
  .object({
    id: z.string(),
    name: z.string(),
    synonym: z.string().optional(),
    description: z.string().optional(),
    formula: z.string(),
    references: z.array(referenceDataSchema).optional(),
  })
  .openapi("CompoundData");

export type CompoundData = z.infer<typeof compoundDataSchema>;
