import { ColorArg } from "@core/types";
import { colord } from "colord";
import React, { FC } from "react";

type Props = {
  radius: number;
  x: number;
  y: number;
  fillColor?: ColorArg;
  strokeColor?: ColorArg;
  strokeWidth?: number;
};

export const Circle: FC<Props> = ({ x, y, radius, fillColor, strokeColor, strokeWidth }) => {
  return (
    <circle
      cx={x}
      cy={y}
      r={radius}
      fill={fillColor && colord(fillColor).toHex()}
      stroke={strokeColor && colord(strokeColor).toHex()}
      strokeWidth={strokeWidth}
    />
  );
};
