import type { CommonState } from "@core/state/common";
import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";

export type CanvasMode = "view" | "edit";

type State = {
  mode: CanvasMode;
};

const initialState: State = {
  mode: "view",
};

const slice = createSlice({
  name: "app/canvasMode",
  initialState,
  reducers: {
    setCanvasMode(state, action: PayloadAction<CanvasMode>) {
      state.mode = action.payload;
    },
    setCanvasModeAsEdit(state) {
      state.mode = "edit";
    },
    setCanvasModeAsView(state) {
      state.mode = "view";
    },
  },
});

export const canvasModeReducer = slice.reducer;
export const CanvasModeActions = slice.actions;

const selectState = (state: CommonState) => state.app.canvasMode;
export const selectCanvasMode = createSelector(selectState, (s) => s.mode);
