import { Tab, Tabs } from "@core/components/mui/Tabs";
import { useAppSelector } from "@core/state/hooks";
import { ProteinModel, ProteinsSelectors } from "@core/state/slices/entities/proteinModelSlice";
import { Box } from "@mui/material";
import { useProteinPanel } from "@viewer/hooks/useProteinPanel";
import { ProteinPane } from "@viewer/propertyPanel/pane/ProteinPane";
import React, { FC, SyntheticEvent, useMemo, useState } from "react";

type Props = { id: string; parentId?: string };

export const OrProteinPane: FC<Props> = ({ id }) => {
  const { protein } = useProteinPanel(id);
  const oneOf = useOneOf(protein);
  const { tabValue, handleTabChange } = useProteinTab(oneOf[0].id);
  if (!protein || !oneOf.length) return <></>;
  return (
    <Box>
      <Tabs
        value={tabValue}
        onChange={handleTabChange}
      >
        {oneOf.map((p, i) => (
          <Tab
            label={p.geneName || p.name || i + 1}
            value={p.id}
            key={p.id}
          />
        ))}
      </Tabs>
      <ProteinPane
        id={tabValue}
        parentId={id}
      />
    </Box>
  );
};

const useOneOf = (protein: ProteinModel) => {
  const allProteins = useAppSelector(ProteinsSelectors.selectAll);
  const oneOf = useMemo(() => {
    return allProteins.filter((p) => protein?.oneOf?.includes(p.id) ?? false);
  }, [protein, allProteins]);
  return oneOf;
};

const useProteinTab = (id: string) => {
  const [tabValue, setTabValue] = useState(id);
  const handleTabChange = (event: SyntheticEvent, newValue: string) => {
    setTabValue(newValue);
  };
  return { tabValue, handleTabChange };
};
