import { extendZod } from "@schema/extendZod";
import { z } from "zod";

extendZod();
export const layoutTagValueDataSchema = z.object({
  key: z.string(),
  label: z.string(),
  description: z.string().optional(),
});
export type LayoutTagValueData = z.infer<typeof layoutTagValueDataSchema>;

export const layoutTagDataSchema = z.object({
  id: z.string().openapi({ example: "mode" }),
  label: z.string().openapi({ example: "Mode" }),
  selectionType: z.enum(["single", "multiple"]),
  defaultValue: z.string().optional(),
  values: z.array(layoutTagValueDataSchema),
});

export type LayoutTagData = z.infer<typeof layoutTagDataSchema>;
