import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";
import type { RootState } from "@viewer/state/store";

export const generalPanelTabIds = {
  pathway: "pathway",
  document: "document",
  view: "view",
  info: "info",
} as const;
export type GeneralPanelTabId = (typeof generalPanelTabIds)[keyof typeof generalPanelTabIds];

type State = {
  generalTab: GeneralPanelTabId;
};

const initialState: State = {
  generalTab: generalPanelTabIds.pathway,
};

const slice = createSlice({
  initialState,
  name: "viewer/tab",
  reducers: {
    setGeneralTab(state, action: PayloadAction<GeneralPanelTabId>) {
      state.generalTab = action.payload;
    },
  },
});

export const viewerTabReducer = slice.reducer;
export const ViewerTabActions = slice.actions;

const selectState = (state: RootState) => state.viewer.tab;
export const selectGeneralTabId = createSelector(selectState, (state) => state.generalTab);
