import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { TagSelectionActions } from "@core/state/slices/app/selection/tagSelection";
import { selectInitialLayoutTagValueIds } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { useEffect } from "react";

export const useInitialTagSelection = () => {
  const dispatch = useAppDispatch();
  const initialLayoutTagValueIds = useAppSelector(selectInitialLayoutTagValueIds);
  useEffect(() => {
    dispatch(TagSelectionActions.setTagSelection(initialLayoutTagValueIds));
  }, [initialLayoutTagValueIds, dispatch]);
};
