import { DefaultMarkers } from "@core/canvas/DefaultMarkers";
import { useTooltip } from "@core/state/hooks/useToolTip";
import Tooltip from "@mui/material/Tooltip";
import React, {
  FC,
  PointerEventHandler,
  ReactNode,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

type Props = {
  fullScreen?: boolean;
  children?: ReactNode;
  gridSize?: number;
  onClickCanvas?: () => void;
  showGrid?: boolean;
};

export const SvgWrapper: FC<Props> = ({
  fullScreen = false,
  gridSize = 50,
  children,
  onClickCanvas,
  showGrid = true,
}) => {
  const { onPointerMove, onPointerUp, onPointerDown, canvasTransform, isGrabbing } =
    useHandleCanvasGrabber(onClickCanvas);
  const { svgRef, wrapperHeight, wrapperWidth } = useHandleSvgSize();

  const { tooltipValue } = useTooltip();
  const { toolTipTitle, isToolTipOpen } = useMemo(() => {
    const toolTipTitle = tooltipValue;
    const isToolTipOpen = tooltipValue !== "";
    return { toolTipTitle, isToolTipOpen };
  }, [tooltipValue]);

  return (
    <Tooltip
      title={toolTipTitle}
      followCursor={true}
      open={isToolTipOpen}
      slotProps={{ popper: { disablePortal: true } }}
    >
      <svg
        viewBox={`0 0 ${wrapperWidth} ${wrapperHeight}`}
        xmlns="http://www.w3.org/2000/svg"
        ref={svgRef}
        style={{ display: "block", width: "100%", height: fullScreen ? "100vh" : "100%" }}
      >
        <defs>
          <pattern
            id="GridPattern"
            x="0"
            y="0"
            width={gridSize}
            height={gridSize}
            patternUnits="userSpaceOnUse"
          >
            <rect
              x="0"
              y="0"
              width={gridSize}
              height={gridSize}
              fill="white"
            />
            <rect
              x="0"
              y="0"
              width="1"
              height={gridSize}
              fill="#00000020"
            />
            <rect
              x="0"
              y="0"
              width={gridSize}
              height="1"
              fill="#00000020"
            />
          </pattern>
        </defs>
        <defs>
          <filter
            x="-0.025"
            y="-0.025"
            width="1.05"
            height="1.05"
            id="solid"
          >
            <feFlood
              floodColor="#FFFFFF"
              floodOpacity={1}
            />
            <feComposite
              in="SourceGraphic"
              operator="over"
            />
          </filter>
        </defs>
        <DefaultMarkers />
        <g
          style={{ cursor: isGrabbing ? "grabbing" : "grab" }}
          onPointerDown={onPointerDown}
          onPointerUp={onPointerUp}
          onPointerMove={onPointerMove}
        >
          <rect
            x={0}
            y={0}
            width={wrapperWidth}
            height={wrapperHeight}
            fill={"#FFF"}
          />
        </g>
        <g
          style={{ pointerEvents: "none" }}
          transform={canvasTransform}
        >
          <rect
            x={wrapperWidth * -1}
            y={wrapperHeight * -1}
            width={wrapperWidth * 3}
            height={wrapperHeight * 3}
            fill={showGrid ? "url(#GridPattern)" : "none"}
          />
          <g>{children}</g>
        </g>
      </svg>
    </Tooltip>
  );
};
const useHandleSvgSize = () => {
  const svgRef = useRef<SVGSVGElement>(null);
  const [wrapperHeight, setWrapperHeight] = useState(0);
  const [wrapperWidth, setWrapperWidth] = useState(0);
  const update = () => {
    if (!svgRef.current?.parentNode) return;
    const parent = svgRef.current.parentNode as HTMLElement;
    setWrapperHeight(parent.clientHeight);
    setWrapperWidth(parent.clientWidth);
  };

  useLayoutEffect(() => {
    if (!svgRef.current?.parentNode) return;
    const parent = svgRef.current.parentNode as HTMLElement;
    setWrapperHeight(parent.clientHeight);
    setWrapperWidth(parent.clientWidth);
    const ro = new ResizeObserver(() => {
      update();
    });
    ro.observe(parent);
    return () => {
      ro.disconnect();
    };
  }, [svgRef]);
  return { svgRef, wrapperHeight, wrapperWidth };
};

const useHandleCanvasGrabber = (onClickCanvas?: () => void, x: number = 100, y: number = 50) => {
  const [canvasTransform, setCanvasTransform] = useState(`translate(${x} ${y})`);
  const [isPressed, setIsPressed] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [cx, setCx] = useState(x);
  const [cy, setCy] = useState(y);
  const [startX, setStartX] = useState(0);
  const [startY, setStartY] = useState(0);

  const onPointerDown: PointerEventHandler = (e) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsPressed(true);
    setStartX(e.screenX);
    setStartY(e.screenY);
    setCanvasTransform(`translate(${cx} ${cy})`);
  };
  const onPointerMove: PointerEventHandler = (e) => {
    if (!isPressed) return;
    setIsDragging(true);
    const dx = e.screenX - startX;
    const dy = e.screenY - startY;
    setCanvasTransform(`translate(${cx + dx} ${cy + dy})`);
  };
  const onPointerUp: PointerEventHandler = (e) => {
    if (!isPressed) return;
    if (!isDragging && onClickCanvas) {
      onClickCanvas();
    }
    e.currentTarget.releasePointerCapture(e.pointerId);
    setIsDragging(false);
    setIsPressed(false);
    const dx = e.screenX - startX;
    const dy = e.screenY - startY;
    setCx(cx + dx);
    setCy(cy + dy);
  };
  return { canvasTransform, onPointerDown, onPointerMove, onPointerUp, isGrabbing: isPressed };
};
