import Box from "@mui/material/Box";
import Stack from "@mui/material/Stack";
import { styled } from "@mui/material/styles";
import Typography from "@mui/material/Typography";
import { BrowserButtons } from "@viewer/browserPanel/components/BrowserButtons";
import { InfoWrapper } from "@viewer/browserPanel/components/InfoWrapper";
import { TreeColumns } from "@viewer/browserPanel/components/TreeColumns";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import { selectIsBrowserPanelOpen, ViewerPanelActions } from "@viewer/state/slices/panelSlice";
import React, { FC } from "react";

type Props = {};
export const BrowserPanel: FC<Props> = ({}) => {
  const { isDrawerOpen, onClickToggleButton } = useDrawerStatus();
  return (
    <Wrapper className={isDrawerOpen ? "open" : "closed"}>
      <Box>
        <Typography
          color={"textPrimary"}
          variant={"h5"}
        >
          Pathway browser
        </Typography>
      </Box>
      <TreeColumns />
      <InfoWrapper />
      <BrowserButtons />
      <ToggleButton
        onClick={onClickToggleButton}
        data-testid={"documentDrawer"}
      >
        <span className={"inner"}>Documents</span>
      </ToggleButton>
    </Wrapper>
  );
};

const useDrawerStatus = () => {
  const isDrawerOpen = useAppSelector(selectIsBrowserPanelOpen);
  const dispatch = useAppDispatch();
  const onClickToggleButton = () => {
    dispatch(ViewerPanelActions.toggleBrowserPanel());
  };
  return { isDrawerOpen, onClickToggleButton };
};

const Wrapper = styled(Stack)(({ theme }) => ({
  width: 640,
  height: "100%",
  position: "absolute",
  top: 0,
  left: 0,
  display: "flex",
  flexDirection: "column",
  gap: "0.5rem",
  padding: "0.5rem",
  boxSizing: "border-box",
  background: theme.palette.background.default,
  transitionDuration: "0.3s",
  transitionProperty: "transform",
  transitionTimingFunction: "ease-in-out",
  ["&.closed"]: {
    transform: "translateX(-100%)",
  },
  ["&.open"]: {
    transform: "translateX(0)",
  },
}));
const ToggleButton = styled(Box)(({ theme }) => ({
  position: "absolute",
  top: 0,
  right: -24,
  width: 24,
  height: "90px",
  background: theme.palette.background.paper,
  borderColor: theme.palette.divider,
  borderStyle: "solid",
  borderWidth: "1px",
  userSelect: "none",
  cursor: "pointer",
  ["& .inner"]: {
    position: "absolute",
    top: "5px",
    left: "2px",
    fontSize: "15px",
    transform: "translateY(-100%) rotate(90deg)",
    transformOrigin: "bottom left",
    color: theme.palette.text.primary,
  },
}));
