import { Markers } from "@core/canvas/Markers";
import { useAppSelector } from "@core/state/hooks";
import { selectCurrentLayoutIds } from "@core/state/selectors/selectCurrentLayoutIds";
import { selectGridSize } from "@core/state/slices/app/gridSlice";
import { ConnectionsSelectors } from "@core/state/slices/entities/connectionModelsSlice";
import { PathwayGraph } from "@viewer/canvas/PathwayGraph";
import React, { useEffect, useLayoutEffect, useRef, useState } from "react";

export const MultiplePathways = () => {
  const { currentLayoutIds, canvasWrapperRef, coordinates } = usePathwayReLayout();
  return (
    <>
      <Markers />
      <g ref={canvasWrapperRef}>
        {currentLayoutIds.map((id, i) => {
          const x = coordinates[i]?.x || 0;
          const y = coordinates[i]?.y || 0;
          return (
            <PathwayGraph
              layoutId={id}
              key={id}
              x={x}
              y={y}
            />
          );
        })}
      </g>
    </>
  );
};

const usePathwayReLayout = () => {
  const currentLayoutIds = useAppSelector(selectCurrentLayoutIds);
  const gridSize = useAppSelector(selectGridSize);
  const canvasWrapperRef = useRef<SVGGElement>(null);
  type Coordinate = { x: number; y: number; w: number; h: number };
  const [coordinates, setCoordinates] = useState<Coordinate[]>([]);
  useLayoutEffect(() => {
    setTimeout(() => {
      if (!canvasWrapperRef.current) return;
      const wrapper = canvasWrapperRef.current;
      const graphs = [...wrapper.querySelectorAll<SVGGElement>("g[data-pathway-frame]")];
      const margin: number = 20;
      const arr = graphs.reduce<Coordinate[]>((acc, current, i) => {
        const prev = acc[acc.length - 1] || { x: 0, y: 0, w: 0, h: 0 };
        const box = current.getBBox();
        const m = i === 0 ? 0 : margin;
        const x = 0;
        const y = prev.y + prev.h + m;
        const w = box.width;
        const h = box.height;
        return [...acc, { x, y, w, h }];
      }, []);
      setCoordinates(arr);
    }, 100);
  }, [currentLayoutIds, gridSize]);

  return { currentLayoutIds, canvasWrapperRef, coordinates };
};
