import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSelector, createSlice } from "@reduxjs/toolkit";
import { EntityType } from "@schema/app/enums";
import { NodeData } from "@schema/app/NodeData";
import { nanoid } from "nanoid";

export type NodeModel = NodeData & { layoutId: string };

const adapter = createEntityAdapter<NodeModel, string>({
  selectId: (node) => node.id,
});

const slice = createSlice({
  name: "entities/nodes",
  initialState: adapter.getInitialState(),
  reducers: {
    addNode: adapter.addOne,
    updateNode: adapter.updateOne,
    upsertNode: adapter.upsertOne,
    removeNode: adapter.removeOne,
    addNodes: adapter.addMany,
    updateNodes: adapter.updateMany,
    upsertNodes: adapter.upsertMany,
    removeNodes: adapter.removeMany,
    setNodes: adapter.setAll,
    removeAllNodes: adapter.removeAll,
  },
});

export const nodesReducer = slice.reducer;
export const NodesActions = slice.actions;
const selectors = adapter.getSelectors<CommonState>((state) => state.entities.nodes);

const selectByLayoutId = createSelector(
  [selectors.selectAll, (state, id: string) => id],
  (nodes, id) => nodes.filter((node) => node.layoutId === id)
);
export const NodesSelectors = { ...selectors, selectByLayoutId };

export const createNewNode = (layoutId: string, type: EntityType): NodeModel => {
  const id = nanoid();
  return {
    id,
    layoutId: layoutId,
    entityId: "",
    x: 0,
    y: 0,
    entityType: type,
  };
};
