import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSelector, createSlice } from "@reduxjs/toolkit";
import { ConnectionData } from "@schema/app/ConnectionData";
import { nanoid } from "nanoid";

export type ConnectionModel = ConnectionData & { layoutId: string };

const adapter = createEntityAdapter<ConnectionModel, string>({
  selectId: (connection) => connection.id,
  sortComparer: (a, b) => a.id.localeCompare(b.id),
});

const slice = createSlice({
  name: "entities/connections",
  initialState: adapter.getInitialState(),
  reducers: {
    addConnection: adapter.addOne,
    updateConnection: adapter.updateOne,
    removeConnection: adapter.removeOne,
    removeConnections: adapter.removeMany,
    removeAllConnections: adapter.removeAll,
    setConnections: adapter.setAll,
    upsertConnection: adapter.upsertOne,
    upsertConnections: adapter.upsertMany,
    addConnections: adapter.addMany,
    updateConnections: adapter.updateMany,
  },
});

export const connectionsReducer = slice.reducer;
export const ConnectionsActions = slice.actions;

// Selectors
const selectors = adapter.getSelectors<CommonState>((state) => state.entities.connections);
const selectByLayoutId = createSelector(
  [selectors.selectAll, (state, id) => id],
  (connections, id) => connections.filter((connection) => connection.layoutId === id)
);
const selectConnectionColors = createSelector(selectors.selectAll, (connections) => {
  const colorSet = connections
    .map((c) => c.strokeColor)
    .filter((color): color is string => typeof color === "string")
    .map((c) => c.toLowerCase())
    .reduce<Set<string>>((acc, color) => acc.add(color), new Set<string>());
  colorSet.add("#000000"); // Ensure black is always included
  return Array.from(colorSet);
});

export const ConnectionsSelectors = {
  ...selectors,
  selectByLayoutId,
  selectConnectionColors,
};

export const createNewConnection = (layoutId: string): ConnectionModel => {
  const id = nanoid();
  return {
    id,
    layoutId: layoutId,
    source: "",
    target: "",
    markerSource: false,
    markerTarget: false,
    shape: "doubleRightAngles",
    orientation: "horizontal",
  };
};
