import { Path } from "@core/canvas/atoms/Path";
import { COLOR_SELECTED } from "@core/consts";
import React, { ComponentProps, FC } from "react";

type PathProps = ComponentProps<typeof Path>;
type Props = {
  clickFn?: () => void;
  isSelected: boolean;
} & PathProps;
export type ConnectionProps = Props;

export const ConnectionElement: FC<Props> = ({
  ax,
  ay,
  bx,
  by,
  r = 10,
  loopMod = 50,
  color = "#000000",
  strokeWidth = 1,
  orientation = "horizontal",
  shape,
  strokeDasharray = [],
  markerStart,
  markerEnd,
  clickFn,
  isSelected,
}) => {
  return (
    <g
      onClick={clickFn}
      style={clickFn && { cursor: "pointer", pointerEvents: "auto" }}
    >
      <Path
        {...{
          ax,
          ay,
          bx,
          by,
          r,
          loopMod,
          color: "#00000000",
          strokeWidth: strokeWidth + 11,
          orientation,
          shape,
        }}
      />

      {shape !== "doubleLine" ? (
        <Path
          color={isSelected ? COLOR_SELECTED : color}
          {...{
            ax,
            ay,
            bx,
            by,
            r,
            loopMod,
            strokeWidth,
            orientation,
            shape,
            strokeDasharray,
            markerStart,
            markerEnd,
          }}
        />
      ) : (
        <>
          <Path
            color={"#00000000"}
            {...{
              ax,
              ay,
              bx,
              by,
              r,
              loopMod,
              strokeWidth,
              orientation,
              shape,
              strokeDasharray,
              markerStart,
              markerEnd,
            }}
          />
          <Path
            color={isSelected ? COLOR_SELECTED : color}
            ax={ax - 2}
            ay={ay}
            bx={bx - 2}
            by={by + (markerEnd ? -6 : 0)}
            {...{
              r,
              loopMod,
              strokeWidth,
              orientation,
              shape,
              strokeDasharray,
            }}
          />
          <Path
            color={isSelected ? COLOR_SELECTED : color}
            ax={ax + 2}
            ay={ay}
            bx={bx + 2}
            by={by + (markerEnd ? -6 : 0)}
            {...{
              r,
              loopMod,
              strokeWidth,
              orientation,
              shape,
              strokeDasharray,
            }}
          />
        </>
      )}
    </g>
  );
};
