import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSelector, createSlice } from "@reduxjs/toolkit";
import { layoutTagValueDataSchema } from "@schema/app/LayoutTagData";
import { extendZod } from "@schema/extendZod";
import { nanoid } from "nanoid";
import z from "zod";

export const TAG_VALUE_DIVIDER = "###";

extendZod();
const schema = layoutTagValueDataSchema.extend({
  id: z.string(),
  tagId: z.string(),
});

export type LayoutTagValueModel = z.infer<typeof schema>;

const adapter = createEntityAdapter<LayoutTagValueModel, string>({
  selectId: (layoutTagValue) => layoutTagValue.id,
});

const slice = createSlice({
  name: "entities/layoutTagValues",
  initialState: adapter.getInitialState(),
  reducers: {
    addLayoutTagValue: adapter.addOne,
    updateLayoutTagValue: adapter.updateOne,
    removeLayoutTagValue: adapter.removeOne,
    removeLayoutTagValues: adapter.removeMany,
    removeAllLayoutTagValues: adapter.removeAll,
    setLayoutTagValues: adapter.setAll,
    upsertLayoutTagValue: adapter.upsertOne,
    upsertLayoutTagValues: adapter.upsertMany,
    addLayoutTagValues: adapter.addMany,
    updateLayoutTagValues: adapter.updateMany,
  },
});

export const layoutTagValueReducer = slice.reducer;
export const LayoutTagValueActions = slice.actions;
export const LayoutTagValueSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.layoutTagValues
);
export const selectInitialLayoutTagValueIds = createSelector(
  LayoutTagValueSelectors.selectAll,
  (values: LayoutTagValueModel[]) => makeInitialTagValueIds(values.map((v) => v.id))
);
export const selectLayoutTagValuesByTagId = createSelector(
  [LayoutTagValueSelectors.selectAll, (state, id) => id],
  (values: LayoutTagValueModel[], id: string): LayoutTagValueModel[] => {
    return values.filter((value) => value.tagId === id);
  }
);

const makeInitialTagValueIds = (values: string[]) => {
  const tagMap = new Map<string, string>();
  for (const value of values) {
    const tagName = value.split(TAG_VALUE_DIVIDER)[0];
    if (!tagMap.has(tagName)) {
      tagMap.set(tagName, value);
    }
  }
  return Array.from(tagMap.values());
};

export const createLayoutTagValue = (label: string): LayoutTagValueModel => {
  return {
    label,
    key: "key",
    id: nanoid(),
    tagId: "tagId",
  };
};

export const __TEST__layoutTagValueModelSlice = {
  makeInitialTagValueIds,
};
