import { Checkbox } from "@core/components/mui/Checkbox";
import { Sheet } from "@core/components/mui/Sheet";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { GridActions, selectGridSize, selectShowGrid } from "@core/state/slices/app/gridSlice";
import { TextField } from "@mui/material";
import FormControl from "@mui/material/FormControl";
import Typography from "@mui/material/Typography";
import React, { FC } from "react";

type Props = {};

export const ViewSettingsPane: FC<Props> = ({}) => {
  const dispatch = useAppDispatch();
  const gridSize = useAppSelector(selectGridSize);
  const showGrid = useAppSelector(selectShowGrid);
  const handleChangeGridSize = (value: string) => {
    dispatch(GridActions.setGridSize(parseFloat(value)));
  };
  const handleChangeShowGrid = (val: boolean) => {
    dispatch(GridActions.setShowGrid(val));
  };

  return (
    <Sheet
      sx={{ maxHeight: "max-content", p: 2, display: "flex", flexDirection: "column", gap: 2 }}
    >
      <FormControl>
        <Typography>Show grid</Typography>
        <Checkbox
          checked={showGrid}
          onChange={(e) => handleChangeShowGrid(e.target.checked)}
        />
      </FormControl>
      <FormControl>
        <TextField
          label={"Grid size"}
          type={"number"}
          value={gridSize}
          onChange={(e) => handleChangeGridSize(e.target.value)}
          slotProps={{ input: { sx: { width: "100%" } } }}
        />
      </FormControl>
    </Sheet>
  );
};
