import { Sheet } from "@core/components/mui/Sheet";
import { Alert, Button, Typography } from "@mui/material";
import { currentVer } from "@schema/const";
import { viewerVersion } from "@viewer/consts/version";
import { useState } from "react";

export const InfoPane = () => {
  const [copyStatus, setCopyStatus] = useState<"idle" | "copying" | "success" | "error">("idle");
  const info = `Viewer version: ${viewerVersion}\nAPI version: ${currentVer}`;

  const handleCopy = async () => {
    setCopyStatus("copying");
    try {
      await navigator.clipboard.writeText(info);
      setCopyStatus("success");
    } catch {
      setCopyStatus("error");
    }
  };

  return (
    <Sheet sx={{ p: 2, display: "flex", flexDirection: "column", gap: 2 }}>
      <Typography sx={{ whiteSpace: "pre-wrap", userSelect: "text" }}>{info}</Typography>
      <Button
        variant="outlined"
        disabled={copyStatus === "copying"}
        onClick={handleCopy}
      >
        Copy info
      </Button>
      {copyStatus === "success" && (
        <Alert
          severity="success"
          role="status"
        >
          Version info copied.
        </Alert>
      )}
      {copyStatus === "error" && (
        <Alert severity="error">
          Could not copy. Please select and copy the version info above.
        </Alert>
      )}
    </Sheet>
  );
};
