import type { CommonState } from "@core/state/common";
import type { Store, ThunkAction, ThunkDispatch, UnknownAction } from "@reduxjs/toolkit";
import { useDispatch, useSelector, useStore } from "react-redux";

export type CommonThunk<Result = void> = ThunkAction<Result, CommonState, unknown, UnknownAction>;
export type CommonDispatch = ThunkDispatch<CommonState, unknown, UnknownAction>;
export const useAppDispatch = useDispatch.withTypes<CommonDispatch>();
export const useAppSelector = useSelector.withTypes<CommonState>();

// イベント時に最新の共通状態を読むため、Providerのストアを返す。
export const useAppStore = useStore.withTypes<Store<CommonState>>();
