import React from "react";
import { ReactStanza } from "../../shared/ReactStanza";
import { App } from "./App";

type StanzaParameters = {
  "tax-ids"?: string;
  "variant-id"?: string;
  "data-url"?: string;
  "grid-size"?: string;
  height?: string;
};

export default class PathwayViewer extends ReactStanza<StanzaParameters> {
  makeApp(): React.ReactElement {
    const params: StanzaParameters = this.params;
    const taxIds = (params["tax-ids"] || "").split(",").map((id: string) => id.trim());
    const variantId = params["variant-id"] || "";
    const dataUrl = params["data-url"] || "";
    const gridSize = params["grid-size"] ? parseInt(params["grid-size"]) : undefined;
    const height = params["height"] ? parseInt(params["height"]) : undefined;
    return (
      <App
        taxIds={taxIds}
        variantId={variantId}
        dataUrl={dataUrl}
        gridSize={gridSize}
        height={height}
      />
    );
  }
}
