import type { CommonState } from "@core/state/common";
import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";

type State = {
  errors: string[];
};
const initialState: State = {
  errors: [],
};

const slice = createSlice({
  name: "errorLog",
  initialState,
  reducers: {
    addError(state, action: PayloadAction<string>) {
      state.errors = [...state.errors, action.payload];
    },
  },
});

export const errorLogReducer = slice.reducer;
export const ErrorLogActions = slice.actions;

const selectState = (state: CommonState) => state.app.errorLog;
export const selectErrorCount = createSelector(selectState, (s) => s.errors.length);
export const selectRecentError = createSelector(selectState, (s) => s.errors.slice(-1)[0]);
