import { canvasModeReducer } from "@core/state/slices/app/canvasModeSlice";
import { gridReducer } from "@core/state/slices/app/gridSlice";
import { labelKeyReducer } from "@core/state/slices/app/labelKeySlice";
import { modalReducer } from "@core/state/slices/app/modal";
import { itemSelectionReducer } from "@core/state/slices/app/selection/itemSelection";
import { tagSelectionReducer } from "@core/state/slices/app/selection/tagSelection";
import { tooltipReducer } from "@core/state/slices/app/tooltip";
import { compoundsReducer } from "@core/state/slices/entities/compoundModelsSlice";
import { connectionsReducer } from "@core/state/slices/entities/connectionModelsSlice";
import { documentsReducer } from "@core/state/slices/entities/documentModelsSlice";
import { layoutsReducer } from "@core/state/slices/entities/layoutModelsSlice";
import { layoutTagReducer } from "@core/state/slices/entities/layoutTagModelSlice";
import { layoutTagRelationsReducer } from "@core/state/slices/entities/layoutTagRelationsSlice";
import { layoutTagValueReducer } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { nodesReducer } from "@core/state/slices/entities/nodeModelsSlice";
import { proteinsReducer } from "@core/state/slices/entities/proteinModelSlice";
import { reactionsReducer } from "@core/state/slices/entities/reactionModelsSlice";
import { referencesReducer } from "@core/state/slices/entities/referenceModelsSlice";
import { errorLogReducer } from "@core/state/slices/errorLogSlice";
import { combineReducers } from "@reduxjs/toolkit";

export const commonReducers = {
  app: combineReducers({
    selections: combineReducers({
      selectedItem: itemSelectionReducer,
      selectedTags: tagSelectionReducer,
    }),
    labelKey: labelKeyReducer,
    grid: gridReducer,
    canvasMode: canvasModeReducer,
    modal: modalReducer,
    tooltip: tooltipReducer,
    errorLog: errorLogReducer,
  }),
  entities: combineReducers({
    documents: documentsReducer,
    layouts: layoutsReducer,
    nodes: nodesReducer,
    connections: connectionsReducer,
    references: referencesReducer,
    reactions: reactionsReducer,
    compounds: compoundsReducer,
    proteins: proteinsReducer,
    layoutTags: layoutTagReducer,
    layoutTagValues: layoutTagValueReducer,
    layoutTagRelations: layoutTagRelationsReducer,
  }),
};

export const commonReducer = combineReducers(commonReducers);
export type CommonState = ReturnType<typeof commonReducer>;
