import { CircleXmarkIcon } from "@core/icons/CircleXmarkIcon";
import Box from "@mui/material/Box";
import Stack from "@mui/material/Stack";
import { styled } from "@mui/material/styles";
import Typography from "@mui/material/Typography";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import {
  BrowserSelectionActions,
  selectBrowserPathwaySelection,
  selectBrowserTaxonSelection,
} from "@viewer/state/slices/browserSelectionSlice";
import React, { FC } from "react";

type Props = {};

export const InfoWrapper: FC<Props> = ({}) => {
  const dispatch = useAppDispatch();
  const selectedTaxons = useAppSelector(selectBrowserTaxonSelection);
  const selectedPathways = useAppSelector(selectBrowserPathwaySelection);
  const selectedTaxonLabels = selectedTaxons.map((label) => label.label).join(", ");
  const selectedPathwayLabels = selectedPathways.map((label) => label.label).join(", ");
  const handleClearTaxonSelection = () => {
    dispatch(BrowserSelectionActions.clearTaxonSelection());
  };
  const handleClearPathwaySelection = () => {
    dispatch(BrowserSelectionActions.clearPathwaySelection());
  };

  return (
    <Wrapper>
      <Row
        label={"Taxon"}
        handleClear={handleClearTaxonSelection}
        value={selectedTaxonLabels}
      />
      <Row
        label={"Pathway"}
        handleClear={handleClearPathwaySelection}
        value={selectedPathwayLabels}
      />
    </Wrapper>
  );
};

const Row: FC<{ label: string; value: string; handleClear: () => void }> = ({
  label,
  handleClear,
  value,
}) => {
  return (
    <>
      <Stack
        direction={"row"}
        sx={{ alignItems: "center", gap: 1 }}
      >
        <Typography
          sx={{ fontSize: 8 }}
          onClick={handleClear}
        >
          <CircleXmarkIcon />
        </Typography>
        <Typography sx={{ fontSize: "small" }}>{label}</Typography>
      </Stack>
      <Box sx={{ display: "flex", alignItems: "center" }}>
        <Typography sx={{ fontSize: "small" }}>{value || "no selection"}</Typography>
      </Box>
    </>
  );
};

const Wrapper = styled(Box)(({ theme }) => ({
  display: "grid",
  gridTemplateColumns: "90px auto",
  padding: "0.5rem",
  borderRadius: 4,
  columnGap: "1rem",
  rowGap: "0.5rem",
  background: theme.palette.background.paper,
  color: theme.palette.text.primary,
  [`svg`]: {
    cursor: "pointer",
    position: "relative",
    top: 2,
  },
}));
