import { COLOR_SELECTED } from "@core/consts";
import React, { FC } from "react";

type Props = {
  x: number;
  y: number;
  width: number;
  height: number;
  isVisible: boolean;
};

export const SelectionRect: FC<Props> = ({ x, y, width, height, isVisible }) => {
  if (!isVisible) return <></>;
  return (
    <rect
      x={x - width / 2 - 2}
      y={y - height / 2 - 2}
      width={width + 4}
      height={height + 4}
      fill={"transparent"}
      stroke={COLOR_SELECTED}
      strokeWidth={2}
    />
  );
  // return (
  //   <circle
  //     cx={x}
  //     cy={y}
  //     r={width}
  //     fill={"transparent"}
  //     stroke={COLOR_SELECTED}
  //     strokeWidth={2}
  //   ></circle>
  // );
};
