import { Checkbox } from "@core/components/mui/Checkbox";
import { useAppSelector } from "@core/state/hooks";
import { selectCanCheckLayoutTag } from "@core/state/selectors/selectCanCheckLayoutTag";
import { selectSelectedLayoutTagIds } from "@core/state/slices/app/selection/tagSelection";
import { LayoutTagValueModel } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { Box } from "@mui/material";
import ListItem from "@mui/material/ListItem";
import ListItemButton from "@mui/material/ListItemButton";
import Typography from "@mui/material/Typography";
import React, { FC } from "react";

type Props = {
  value: LayoutTagValueModel;
  onClick: (valueId: string) => void;
};
export const LayoutListItem: FC<Props> = ({ value, onClick }) => {
  const currentLayoutTagIds = useAppSelector(selectSelectedLayoutTagIds);
  const disabled = useAppSelector((state) => selectCanCheckLayoutTag(state, value.id)) === false;

  return (
    <ListItem sx={{ p: 0 }}>
      <ListItemButton
        sx={{ gap: 1, px: 1 }}
        onClick={() => onClick(value.id)}
        disabled={disabled}
      >
        <Box sx={{ flexShrink: 0 }}>
          <Checkbox
            color="primary"
            checked={currentLayoutTagIds.includes(value.id)}
            disabled={disabled}
          />
        </Box>
        <Typography
          sx={{
            textOverflow: "ellipsis",
            overflow: "hidden",
            whiteSpace: "nowrap",
            userSelect: "none",
          }}
        >
          {value.label}
        </Typography>
      </ListItemButton>
    </ListItem>
  );
};
