import type { CommonState } from "@core/state/common";
import { selectSelectedItemId } from "@core/state/slices/app/selection/itemSelection";
import { NodeModel, NodesSelectors } from "@core/state/slices/entities/nodeModelsSlice";
import { createSelector } from "@reduxjs/toolkit";

export const selectSelectedNodeModel = createSelector(
  [(state: CommonState) => state, selectSelectedItemId],
  (state, selectedItemId): NodeModel | undefined => {
    return selectedItemId !== null ? NodesSelectors.selectById(state, selectedItemId) : undefined;
  }
);
