import { Point } from "@core/types";

export const findCircumCircleCenter = (A: Point, B: Point, C: Point): Point & { r: number } => {
  function calculateMidpoint(P: Point, Q: Point): Point {
    const x = (P.x + Q.x) / 2;
    const y = (P.y + Q.y) / 2;
    return { x, y };
  }

  // 傾きを計算する関数
  function calculateSlope(P: Point, Q: Point): number | null {
    if (Q.x - P.x === 0) return null; // 垂直な線の場合
    return (Q.y - P.y) / (Q.x - P.x);
  }

  // 傾きから垂直な傾きを計算する関数
  function perpendicularSlope(slope: number | null): number | null {
    if (slope === 0) return null; // 水平な線の場合
    if (slope === null) return 0; // 垂直な線の場合
    return -1 / slope;
  }

  // 2直線の交点を求める関数
  function findIntersection(
    line1: [number, number, number],
    line2: [number, number, number]
  ): Point | null {
    const [a1, b1, c1] = line1;
    const [a2, b2, c2] = line2;

    const determinant = a1 * b2 - a2 * b1;
    if (determinant === 0) return null; // 並行または重なる線の場合

    const x = (b2 * c1 - b1 * c2) / determinant;
    const y = (a1 * c2 - a2 * c1) / determinant;
    return { x, y };
  }

  // 中点と傾きから直線の方程式(ax + by = c)の係数を求める関数
  function lineFromPointAndSlope(point: Point, slope: number | null): [number, number, number] {
    if (slope === null) {
      // 垂直な線
      return [1, 0, point.x];
    } else {
      // y = slope * x + b
      const b = point.y - slope * point.x;
      return [-slope, 1, b]; // slope * x - y = -b
    }
  }

  // 各辺の中点と垂直な傾きを計算
  const midAB = calculateMidpoint(A, B);
  const midBC = calculateMidpoint(B, C);
  const slopeAB = perpendicularSlope(calculateSlope(A, B));
  const slopeBC = perpendicularSlope(calculateSlope(B, C));

  // 垂直二等分線の方程式を求める
  const lineAB = lineFromPointAndSlope(midAB, slopeAB);
  const lineBC = lineFromPointAndSlope(midBC, slopeBC);

  // 2直線の交点（外心）を求める
  const circumcenter = findIntersection(lineAB, lineBC);

  // 外心と頂点Aの距離（半径）を計算
  if (!circumcenter) return { x: 0, y: 0, r: 0 };
  const radius = Math.sqrt((circumcenter.x - A.x) ** 2 + (circumcenter.y - A.y) ** 2);

  // 外接円の方程式を返す
  return { ...circumcenter, r: radius };
};
