import { SvgWrapper } from "@core/canvas/SvgWrapper";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { GridActions, selectGridSize, selectShowGrid } from "@core/state/slices/app/gridSlice";
import { ItemSelectionActions } from "@core/state/slices/app/selection/itemSelection";
import React, { FC, PropsWithChildren, WheelEventHandler } from "react";

type Props = {} & PropsWithChildren;

export const PathwayCanvas: FC<Props> = ({ children }) => {
  const dispatch = useAppDispatch();
  const gridSize = useAppSelector(selectGridSize);
  const showGrid = useAppSelector(selectShowGrid);
  const onClickCanvas = () => {
    dispatch(ItemSelectionActions.setSelectedItemId(null));
  };
  const onWheelCanvas: WheelEventHandler = (e) => {
    const size = gridSize + (e.deltaY > 0 ? 1 : -1) * 2;
    dispatch(GridActions.setGridSize(size));
  };

  return (
    <div
      style={{ height: "100%", width: "100%" }}
      id="canvasWrapper"
      onWheel={onWheelCanvas}
    >
      <SvgWrapper
        gridSize={gridSize}
        onClickCanvas={onClickCanvas}
        showGrid={showGrid}
      >
        {children}
      </SvgWrapper>
    </div>
  );
};
