import { ScrollWrapper } from "@core/components/atoms/ScrollWrapper";
import { Tab, Tabs } from "@core/components/mui/Tabs";
import { useAppSelector } from "@core/state/hooks";
import { selectSelectedNodeModel } from "@core/state/selectors/selectSelectedNodeModel";
import Box from "@mui/material/Box";
import { CompoundPane } from "@viewer/propertyPanel/pane/CompoundPane";
import { ProteinPane } from "@viewer/propertyPanel/pane/ProteinPane";
import { ReactionPane } from "@viewer/propertyPanel/pane/ReactionPane";
import React, { FC, useMemo } from "react";

type Props = {};

export const NodePanel: FC<Props> = ({}) => {
  const node = useAppSelector(selectSelectedNodeModel);
  const entityType = node?.entityType;
  const entityId = node?.entityId;
  const tabLabel = useMemo(() => {
    switch (entityType) {
      case "compound":
      case "subCompound":
        return "Compound";
      case "reaction":
        return "Reaction";
      case "protein":
        return "Protein";
      default:
        return "";
    }
  }, [entityType]);
  return (
    <Box sx={{ height: "100%", overflow: "hidden", display: "flex", flexDirection: "column" }}>
      <Tabs value={0}>
        <Tab
          value={0}
          label={tabLabel}
        />
      </Tabs>
      <ScrollWrapper>
        {entityId && entityType === "compound" && <CompoundPane id={entityId} />}
        {entityId && entityType === "subCompound" && <CompoundPane id={entityId} />}
        {entityId && entityType === "reaction" && <ReactionPane id={entityId} />}
        {entityId && entityType === "protein" && <ProteinPane id={entityId} />}
      </ScrollWrapper>
    </Box>
  );
};
