import type { CommonState } from "@core/state/common";
import { TAG_VALUE_DIVIDER } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";

type State = {
  layoutTagIds: string[];
};
const initialState: State = {
  layoutTagIds: [],
};

const slice = createSlice({
  name: "app/selections/tag",
  initialState,
  reducers: {
    setTagSelection(state, action: PayloadAction<string[]>) {
      state.layoutTagIds = action.payload;
    },
    mergeTagSelection(state, action: PayloadAction<{ valueId: string; isMultiple: boolean }>) {
      const { valueId, isMultiple } = action.payload;
      const prev = state.layoutTagIds;
      const newTags = mergeTags(prev, valueId, isMultiple);
      state.layoutTagIds = newTags;
    },
  },
});

export const TagSelectionActions = slice.actions;
export const tagSelectionReducer = slice.reducer;
const selectState = (state: CommonState) => state.app.selections.selectedTags;
export const selectSelectedLayoutTagIds = createSelector(selectState, (s) => s.layoutTagIds);

const mergeTags = (current: string[], incoming: string, isMultiple: boolean): string[] => {
  if (!incoming.split(TAG_VALUE_DIVIDER)[1]) throw new Error("Invalid tag value id");
  const tagId = incoming.split(TAG_VALUE_DIVIDER)[0];
  const targetTagValues = current.filter((t) => t.split(TAG_VALUE_DIVIDER)[0] === tagId);
  const otherTagValues = current.filter((t) => t.split(TAG_VALUE_DIVIDER)[0] !== tagId);

  const nextValues = isMultiple ? selectMultiple(targetTagValues, incoming) : [incoming];

  //
  return [...nextValues, ...otherTagValues].sort();
};

const selectMultiple = (prev: string[], value: string) => {
  const valueIndex = prev.indexOf(value);
  if (valueIndex === -1) {
    return [...prev, value];
  }
  if (prev.length === 1) {
    return prev;
  }
  return prev.filter((v) => v !== value);
};
