import { Sheet } from "@core/components/mui/Sheet";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { LabelKeyActions, selectCompoundLabelKey } from "@core/state/slices/app/labelKeySlice";
import { CompoundLabel, CompoundsSelectors } from "@core/state/slices/entities/compoundModelsSlice";
import { Button } from "@mui/material";
import { FieldSet } from "@viewer/propertyPanel/sub/FieldSet";
import { ReferenceList } from "@viewer/propertyPanel/sub/ReferenceList";
import React, { FC } from "react";

type Props = {
  id: string;
};

export const CompoundPane: FC<Props> = ({ id }) => {
  const dispatch = useAppDispatch();
  const compound = useAppSelector((state) => CompoundsSelectors.selectById(state, id));
  const currentLabelKey = useAppSelector(selectCompoundLabelKey);
  const canExtend = false;
  //
  if (!compound) return <></>;
  //
  const onCheckLabel = (value: CompoundLabel) => {
    const next = currentLabelKey === value ? null : value;
    dispatch(LabelKeyActions.setCompoundLabelKey(next));
    dispatch(LabelKeyActions.setSubCompoundLabelKey(next));
  };

  return (
    <Sheet
      sx={{ maxHeight: "max-content", p: 2, display: "flex", flexDirection: "column", gap: 2 }}
    >
      <FieldSet
        title={"Name"}
        checkBoxProps={{
          checked: currentLabelKey === "name",
          onClick: () => onCheckLabel("name"),
        }}
      >
        {compound.name}
      </FieldSet>
      <FieldSet
        title={"Formula"}
        checkBoxProps={{
          checked: currentLabelKey === "formula",
          onClick: () => onCheckLabel("formula"),
        }}
      >
        {compound.formula}
      </FieldSet>
      <FieldSet title={"Description"}>{compound.description}</FieldSet>
      <ReferenceList parentId={id} />

      {canExtend && (
        <Button
          variant={"contained"}
          disableElevation
          sx={{ mt: 4, width: "100%" }}
        >
          Load connected pathway
        </Button>
      )}
    </Sheet>
  );
};
