import { commonReducers } from "@core/state/common";
import { combineReducers, configureStore } from "@reduxjs/toolkit";
import { browserSelectionReducer } from "@viewer/state/slices/browserSelectionSlice";
import { currentViewerDocumentReducer } from "@viewer/state/slices/currentDocumentSlice";
import { viewerPanelReducer } from "@viewer/state/slices/panelSlice";
import { viewerTabReducer } from "@viewer/state/slices/tabSlice";
export const store = configureStore({
  reducer: {
    ...commonReducers,
    viewer: combineReducers({
      panel: viewerPanelReducer,
      browser: browserSelectionReducer,
      tab: viewerTabReducer,
      currentDocument: currentViewerDocumentReducer,
    }),
  },
});
export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
