import { ScrollWrapper } from "@core/components/atoms/ScrollWrapper";
import { Sheet } from "@core/components/mui/Sheet";
import { DocumentTreeData } from "@core/types";
import { CircularProgress, Skeleton } from "@mui/material";
import Box from "@mui/material/Box";
import Stack from "@mui/material/Stack";
import { styled } from "@mui/material/styles";
import Typography from "@mui/material/Typography";
import { SimpleTreeView } from "@mui/x-tree-view/SimpleTreeView";
import { StyledTreeItem, TreeItemLabel } from "@viewer/browserPanel/components/StyledTreeItem";
import React, { FC } from "react";

type Props = {
  treeData: DocumentTreeData | null;
  isPending: boolean;
  setSelections: (item: TreeItemLabel) => void;
  selections: TreeItemLabel[];
  selectType: "single" | "multiple";
};

export const DocumentTree: FC<Props> = ({ treeData, isPending, setSelections, selections }) => {
  return (
    <Stack sx={{ height: "100%", position: "relative" }}>
      <ScrollWrapper>
        {!treeData || !treeData?.children ? (
          <Stack sx={{ paddingBlock: 1, paddingInline: 2, lineHeight: 1.8, gap: 1 }}>
            <Skeleton
              variant="rectangular"
              animation={false}
              width={"100%"}
              sx={{ bgcolor: "grey.400", fontSize: "1rem" }}
            />
            <Skeleton
              variant="rectangular"
              animation={false}
              width={"80%"}
              sx={{ bgcolor: "grey.400", fontSize: "1rem" }}
            />
            <Skeleton
              variant="rectangular"
              animation={false}
              width={"80%"}
              sx={{ bgcolor: "grey.400", fontSize: "1rem" }}
            />
          </Stack>
        ) : (
          <Sheet sx={{ padding: 1, background: "transparent" }}>
            <SimpleTreeView>
              {treeData.children!.map((node) => renderTree(node, selections, setSelections))}
            </SimpleTreeView>
          </Sheet>
        )}
      </ScrollWrapper>
      {isPending && (
        <LoadingIndicator>
          <CircularProgress />
        </LoadingIndicator>
      )}
    </Stack>
  );
};

const renderTree = (
  node: DocumentTreeData,
  selections: TreeItemLabel[] = [],
  setSelections: (item: TreeItemLabel) => void
) => (
  <StyledTreeItem
    key={node.id}
    itemId={node.id}
    data={node}
    setSelections={setSelections}
    selections={selections}
  >
    {Array.isArray(node.children)
      ? node.children.map((node) => renderTree(node, selections, setSelections))
      : null}
  </StyledTreeItem>
);

const LoadingIndicator = styled(Box)({
  position: "absolute",
  inset: 0,
  zIndex: 1,
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  backgroundColor: "rgba(0, 0, 0, 0.7)",
});
