import { PathwayCanvas } from "@core/canvas/PathwayCanvas";
import { useAppDispatch } from "@core/state/hooks";
import { CanvasModeActions } from "@core/state/slices/app/canvasModeSlice";
import { GridActions } from "@core/state/slices/app/gridSlice";
import { Alert, Snackbar } from "@mui/material";
import { BrowserPanel } from "@viewer/browserPanel/BrowserPanel";
import { AppSnackBar } from "@viewer/canvas/AppSnackBar";
import { MultiplePathways } from "@viewer/canvas/MultiplePathways";
import { useInitialDocument } from "@viewer/hooks/useInitialDocument";
import { useInitialTagSelection } from "@viewer/hooks/useInitialTagSelection";
import { useLoadPathways } from "@viewer/hooks/useLoadPathways";
import { ImportModal } from "@viewer/modal/ImportModal";
import { PropertyPanel } from "@viewer/propertyPanel/PropertyPanel";
import React, { FC, useEffect } from "react";

type Props = {
  documentBrowser?: boolean;
  taxIds?: string[];
  variantId?: string;
  dataUrl?: string;
  gridSize?: number;
  height?: number;
};

export const PathwayViewer: FC<Props> = ({
  documentBrowser = true,
  taxIds = [],
  variantId = "",
  dataUrl = "",
  gridSize,
  height,
}) => {
  const dispatch = useAppDispatch();

  useEffect(() => {
    //todo consolidate reset app logic
    dispatch(CanvasModeActions.setCanvasModeAsView());
    dispatch(GridActions.hideGrid());
  }, [dispatch]);

  useLoadPathways();
  useInitialDocument({ taxIds, variantId, dataUrl });
  useInitialTagSelection();
  // const { dataUrl } = useUrlParams();

  useEffect(() => {
    if (gridSize && gridSize > 0) {
      dispatch(GridActions.setGridSize(gridSize));
    }
  }, [gridSize, dispatch]);
  const heightStyle = height ? `${height}px` : "100%";

  return (
    <div
      style={{
        height: heightStyle,
        width: "100%",
        overflow: "hidden",
        position: "relative",
      }}
    >
      <PathwayCanvas>
        <MultiplePathways />
      </PathwayCanvas>
      <PropertyPanel />
      {documentBrowser && <BrowserPanel />}
      <ImportModal />
      <AppSnackBar />
    </div>
  );
};
