import { CompoundElement } from "@core/canvas/elements/CompoundElement";
import { composeNodeElementProps, NodeObjProps } from "@core/canvas/node/types";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { useIsItemSelected } from "@core/state/hooks/useIsItemSelected";
import {
  selectCompoundLabelKey,
  selectSubCompoundLabelKey,
} from "@core/state/slices/app/labelKeySlice";
import { ItemSelectionActions } from "@core/state/slices/app/selection/itemSelection";
import { CompoundsSelectors } from "@core/state/slices/entities/compoundModelsSlice";
import React, { FC } from "react";

export const CompoundNodeObject: FC<NodeObjProps> = ({ model, grid }) => {
  const dispatch = useAppDispatch();
  const entity = useAppSelector((state) => CompoundsSelectors.selectById(state, model.entityId));
  const isSelected = useIsItemSelected(model.id);
  const compoundLabelKey = useAppSelector(selectCompoundLabelKey);
  const subCompoundLabelKey = useAppSelector(selectSubCompoundLabelKey);
  if (!entity) return <></>;
  //
  const targetLabelKey = model.entityType === "compound" ? compoundLabelKey : subCompoundLabelKey;
  const isSub = model.entityType === "subCompound";
  const label: string = targetLabelKey ? (entity[targetLabelKey] ?? "--") : "";
  const onSelect = () => {
    dispatch(ItemSelectionActions.setSelectedItemId(model.id));
  };
  return (
    <CompoundElement
      {...composeNodeElementProps(model, grid, label, isSelected, onSelect)}
      sub={isSub}
      labelWidth={grid}
    />
  );
};
