import { findTriangleVertices } from "@core/canvas/utils/findTriangleVertices";
import { ColorArg } from "@core/types";
import { colord } from "colord";
import React, { FC } from "react";

type Props = {
  x: number;
  y: number;
  height: number;
  angle: number;
  direction: number;
  fillColor?: ColorArg;
  strokeColor?: ColorArg;
  strokeWidth?: number;
};

export const Triangle: FC<Props> = ({
  x,
  y,
  height,
  angle,
  direction,
  fillColor,
  strokeColor,
  strokeWidth,
}) => {
  return (
    <path
      d={makePath(x, y, height, angle, direction)}
      fill={fillColor && colord(fillColor).toHex()}
      stroke={strokeColor && colord(strokeColor).toHex()}
      strokeWidth={strokeWidth}
    />
  );
};

const makePath = (
  x: number,
  y: number,
  height: number,
  angle: number,
  direction: number
): string => {
  const [v2, v3] = findTriangleVertices({ x, y }, height, angle, direction);
  const p1 = `${x} ${y}`;
  const p2 = `${v2.x} ${v2.y}`;
  const p3 = `${v3.x} ${v3.y}`;
  return `M ${p1} L ${p2} L ${p3} ${p1} Z`;
};
