import { ProteinElement } from "@core/canvas/elements/ProteinElement";
import { composeNodeElementProps, NodeObjProps } from "@core/canvas/node/types";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { useIsItemSelected } from "@core/state/hooks/useIsItemSelected";
import { selectHasHorizontalConnections } from "@core/state/selectors/selectHasHorizontalConnections";
import { selectProteinLabelKey } from "@core/state/slices/app/labelKeySlice";
import { ItemSelectionActions } from "@core/state/slices/app/selection/itemSelection";
import {
  ProteinLabel,
  ProteinModel,
  ProteinsSelectors,
} from "@core/state/slices/entities/proteinModelSlice";
import { ReactionModel, ReactionsSelectors } from "@core/state/slices/entities/reactionModelsSlice";
import React, { FC } from "react";

export const ProteinNodeObject: FC<NodeObjProps> = ({ model, grid }) => {
  const dispatch = useAppDispatch();
  const labelKey = useAppSelector(selectProteinLabelKey);
  const protein = useAppSelector((state) => ProteinsSelectors.selectById(state, model.entityId));
  const reaction = useAppSelector((state) =>
    ReactionsSelectors.selectById(state, protein?.reactionId ?? "")
  );
  const isSelected = useIsItemSelected(model.id);
  const hasHorizontal = useAppSelector((state) => selectHasHorizontalConnections(state, model.id));
  const placement = hasHorizontal ? "bottom" : "right";
  // const placement = "bottom";
  const onSelect = () => {
    dispatch(ItemSelectionActions.setSelectedItemId(model.id));
  };
  if (!protein) return <></>;
  if (!reaction) {
    console.warn("Reaction not found for protein", protein);
    return <></>;
  }
  const label = findProteinLabel(protein, reaction, labelKey);
  return (
    <ProteinElement
      {...composeNodeElementProps(model, grid, label, isSelected, onSelect)}
      placement={placement}
    />
  );
};

const findProteinLabel = (
  protein: ProteinModel,
  reaction: ReactionModel,
  labelKey: ProteinLabel
): string => {
  if (!labelKey) return "";
  let label: string | undefined = "";
  switch (labelKey) {
    case "enzymeCode":
      label = reaction.enzymeCode;
      break;
    case "reactionName":
      label = reaction.name;
      break;
    default:
      label = protein[labelKey];
  }
  if (!label) label = "----";
  return label;
};
