import type { CommonState } from "@core/state/common";
import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";

type State = {
  id: string | null;
};
const initialState: State = {
  id: null,
};
const slice = createSlice({
  name: "app/modal",
  initialState,
  reducers: {
    openModal(state, action: PayloadAction<string>) {
      state.id = action.payload;
    },
    closeModal(state) {
      state.id = null;
    },
  },
});
export const modalReducer = slice.reducer;
export const ModalActions = slice.actions;

const selectState = (state: CommonState) => state.app.modal;
export const selectCurrentModalId = createSelector(selectState, (s) => s.id);
export const selectIsModalOpen = createSelector(selectState, (s) => s.id !== null);
