import { EmptyElement } from "@core/canvas/elements/EmptyElement";
import { composeNodeElementProps, NodeObjProps } from "@core/canvas/node/types";
import { useAppDispatch } from "@core/state/hooks";
import { useIsItemSelected } from "@core/state/hooks/useIsItemSelected";
import { ItemSelectionActions } from "@core/state/slices/app/selection/itemSelection";
import React, { FC } from "react";

export const EmptyNodeObject: FC<NodeObjProps> = ({ model, grid, mode = "edit" }) => {
  const dispatch = useAppDispatch();
  const isSelected = useIsItemSelected(model.id);
  const onSelect = () => {
    dispatch(ItemSelectionActions.setSelectedItemId(model.id));
  };
  return (
    <EmptyElement
      {...composeNodeElementProps(model, grid, "", isSelected, onSelect)}
      mode={mode}
    />
  );
};
