import type { CommonState } from "@core/state/common";
import { isLayoutMatches } from "@core/state/selectors/selectCurrentLayoutIds";
import { selectSelectedLayoutTagIds } from "@core/state/slices/app/selection/tagSelection";
import { LayoutsSelectors } from "@core/state/slices/entities/layoutModelsSlice";
import {
  LayoutTagModel,
  LayoutTagSelectors,
} from "@core/state/slices/entities/layoutTagModelSlice";
import { LayoutTagRelationSelectors } from "@core/state/slices/entities/layoutTagRelationsSlice";
import { TAG_VALUE_DIVIDER } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { createSelector } from "@reduxjs/toolkit";

type OrganizedTagSelection = {
  id: string;
  selectionType: LayoutTagModel["selectionType"];
  values: string[];
};

export const selectCanCheckLayoutTag = createSelector(
  [
    selectSelectedLayoutTagIds,
    LayoutsSelectors.selectAll,
    LayoutTagSelectors.selectAll,
    LayoutTagRelationSelectors.selectAll,
    (state: CommonState, valueId: string) => valueId,
  ],
  (currentSelection, layouts, tags, relations, target) => {
    const currentTags = organizeCurrentTagSelection(currentSelection, tags);
    const targetTag = organizeTargetTagInfo(target, tags);
    const nextTags = mergeSelection(currentTags, targetTag);
    const flattenedNextTags = flattenTags(nextTags);
    return flattenedNextTags.every((arr) => {
      return layouts.some((layout) => isLayoutMatches(layout.id, arr, relations));
    });
  }
);

const organizeTargetTagInfo = (target: string, tags: LayoutTagModel[]): OrganizedTagSelection => {
  const [tagId, tagValue] = target.split(TAG_VALUE_DIVIDER);
  return {
    id: tagId,
    selectionType: tags.find((t) => t.id === tagId)?.selectionType ?? "single",
    values: [tagValue],
  };
};

const organizeCurrentTagSelection = (
  currentSelection: string[],
  tags: LayoutTagModel[]
): OrganizedTagSelection[] => {
  return currentSelection.reduce<OrganizedTagSelection[]>((acc, value) => {
    const [tagId, tagValue] = value.split(TAG_VALUE_DIVIDER);
    const existingTag = acc.find((t) => t.id === tagId);
    if (existingTag) {
      existingTag.values.push(tagValue);
    } else {
      acc.push({
        id: tagId,
        selectionType: tags.find((t) => t.id === tagId)?.selectionType ?? "single",
        values: [tagValue],
      });
    }
    return [...acc];
  }, []);
};

const flattenTags = (tags: OrganizedTagSelection[]): string[][] => {
  const multipleTags = tags.filter((tag) => tag.selectionType === "multiple");
  const multipleCombinations = generateCombinations(multipleTags, TAG_VALUE_DIVIDER);
  const singleTags = tags.filter((tag) => tag.selectionType === "single");
  const singleValues = singleTags.map((tag) => `${tag.id}${TAG_VALUE_DIVIDER}${tag.values[0]}`);

  return multipleCombinations.map((combination) => [...combination, ...singleValues].sort());
};

const mergeSelection = (
  current: OrganizedTagSelection[],
  target: OrganizedTagSelection
): OrganizedTagSelection[] => {
  if (target.selectionType === "single") {
    return [...current.filter((tag) => tag.id !== target.id), target];
  } else {
    const existingTag = current.find((tag) => tag.id === target.id);
    const newTags = [...(existingTag?.values ?? []), ...target.values].sort();
    const updatedTag: OrganizedTagSelection = {
      id: target.id,
      selectionType: target.selectionType,
      values: Array.from(new Set(newTags)),
    };
    return [...current.filter((tag) => tag.id !== target.id), updatedTag];
  }
};

const generateCombinations = (
  obj: Pick<OrganizedTagSelection, "id" | "values">[],
  divider: string
): string[][] => {
  return obj.reduce<string[][]>(
    (acc, { id, values }) => {
      const next: string[][] = [];
      for (const prev of acc) {
        for (const val of values) {
          next.push([...prev, `${id}${divider}${val}`]);
        }
      }
      return next;
    },
    [[]]
  );
};

export const __TEST__selectCanCheckLayoutTag = {
  mergeSelection,
  flattenTags,
  generateCombinations,
};
