import { DocumentTreeData } from "@core/types";
import Box from "@mui/material/Box";
import { styled } from "@mui/material/styles";
import { useQuery } from "@tanstack/react-query";
import { DocumentTree } from "@viewer/browserPanel/components/DocumentTree";
import { TreeItemLabel } from "@viewer/browserPanel/components/StyledTreeItem";
import { API_PATHWAY_TREE, API_TAXON_TREE } from "@viewer/consts/api";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import {
  BrowserSelectionActions,
  selectBrowserPathwaySelection,
  selectBrowserTaxonSelection,
} from "@viewer/state/slices/browserSelectionSlice";
import React, { FC, useRef } from "react";

type Props = {};

const usePathwayTreeQuery = (taxIds: string) => {
  const loadPathwayTree = async () => {
    const params = new URLSearchParams({ tax_ids: taxIds });
    const res = await fetch(API_PATHWAY_TREE + "?" + params.toString());
    const data: DocumentTreeData = await res.json();
    return data;
  };
  const prevRef = useRef<DocumentTreeData>(null);
  const { isPending, data } = useQuery<DocumentTreeData>({
    queryKey: ["pathwayTree", { taxId: taxIds }],
    queryFn: loadPathwayTree,
    staleTime: Infinity,
  });
  // TODO: 再取得中・失敗後も前のツリーを残す挙動と読み込み表示を保ち、refによる保持を見直す。
  if (data) {
    // oxlint-disable-next-line react/refs -- 前回の成功データを保持する既存動作を当面維持する。
    prevRef.current = data;
  }
  // oxlint-disable-next-line react/refs -- 取得結果がない間も前のツリーを表示する。
  return { isPending, data: prevRef.current };
};
const useTaxonTreeQuery = (pathwayId: string) => {
  const loadTaxonTree = async () => {
    const params = new URLSearchParams({ pathway_id: pathwayId });
    const res = await fetch(API_TAXON_TREE + "?" + params.toString());
    const data: DocumentTreeData = await res.json();
    return data;
  };
  const prevRef = useRef<DocumentTreeData>(null);
  const { isPending, data } = useQuery<DocumentTreeData>({
    queryKey: ["taxonTree", { pathwayId }],
    queryFn: loadTaxonTree,
    staleTime: Infinity,
  });
  // TODO: 再取得中・失敗後も前のツリーを残す挙動と読み込み表示を保ち、refによる保持を見直す。
  if (data) {
    // oxlint-disable-next-line react/refs -- 前回の成功データを保持する既存動作を当面維持する。
    prevRef.current = data;
  }
  // oxlint-disable-next-line react/refs -- 取得結果がない間も前のツリーを表示する。
  return { isPending, data: prevRef.current };
};

const useTreeData = () => {
  const dispatch = useAppDispatch();
  const taxonSelection = useAppSelector(selectBrowserTaxonSelection);
  const pathwaySelection = useAppSelector(selectBrowserPathwaySelection);

  const { isPending: isPathwayPending, data: pathwayTree } = usePathwayTreeQuery(
    taxonSelection.map((item) => item.id).join(",")
  );
  const { isPending: isTaxonPending, data: taxonTree } = useTaxonTreeQuery(
    pathwaySelection.map((item) => item.id).join(",")
  );
  const togglePathwaySelection = (data: TreeItemLabel) => {
    dispatch(BrowserSelectionActions.setPathwaySelection(data));
  };
  const toggleTaxonSelection = (data: TreeItemLabel) => {
    dispatch(BrowserSelectionActions.mergeTaxonSelection(data));
  };
  return {
    taxonTree,
    pathwayTree,
    isPathwayPending,
    isTaxonPending,
    taxonSelection,
    pathwaySelection,
    togglePathwaySelection,
    toggleTaxonSelection,
  };
};

export const TreeColumns: FC<Props> = () => {
  const {
    pathwayTree,
    taxonTree,
    isPathwayPending,
    isTaxonPending,
    togglePathwaySelection,
    toggleTaxonSelection,
    taxonSelection,
    pathwaySelection,
  } = useTreeData();
  return (
    <Wrapper>
      <Box sx={{ flexGrow: 0, width: "50%" }}>
        <DocumentTree
          treeData={taxonTree}
          isPending={isTaxonPending}
          setSelections={toggleTaxonSelection}
          selectType={"multiple"}
          selections={taxonSelection}
        />
      </Box>
      <Box sx={{ flexGrow: 0, width: "50%" }}>
        <DocumentTree
          treeData={pathwayTree}
          isPending={isPathwayPending}
          selections={pathwaySelection}
          setSelections={togglePathwaySelection}
          selectType={"single"}
        />
      </Box>
    </Wrapper>
  );
};
const Wrapper = styled(Box)(({ theme }) => ({
  display: "flex",
  flexDirection: "row",
  flexGrow: 1,
  flexShrink: 1,
  overflow: "hidden",
  background: theme.palette.background.paper,
  borderRadius: 4,
}));
