import type { CommonState } from "@core/state/common";
import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";

export const INITIAL_GRID_SIZE = 75;
type State = {
  showGrid: boolean;
  gridSize: number;
};

const initialState: State = {
  showGrid: true,
  gridSize: INITIAL_GRID_SIZE,
};

const slice = createSlice({
  name: "app/grid",
  initialState,
  reducers: {
    setShowGrid(state, action: PayloadAction<boolean>) {
      state.showGrid = action.payload;
    },
    showGrid(state) {
      state.showGrid = true;
    },
    hideGrid(state) {
      state.showGrid = false;
    },
    setGridSize(state, action: PayloadAction<number>) {
      state.gridSize = action.payload;
    },
  },
});

export const gridReducer = slice.reducer;
export const GridActions = slice.actions;

const selectState = (state: CommonState) => state.app.grid;
export const selectShowGrid = createSelector(selectState, (s) => s.showGrid);
export const selectGridSize = createSelector(selectState, (s) => s.gridSize);
