import { selectSelectedLayoutTagIds } from "@core/state/slices/app/selection/tagSelection";
import { LayoutModel, LayoutsSelectors } from "@core/state/slices/entities/layoutModelsSlice";
import {
  LayoutTagRelationModel,
  LayoutTagRelationSelectors,
} from "@core/state/slices/entities/layoutTagRelationsSlice";
import { TAG_VALUE_DIVIDER } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { createSelector } from "@reduxjs/toolkit";

export const selectCurrentLayoutIds = createSelector(
  LayoutsSelectors.selectAll,
  LayoutTagRelationSelectors.selectAll,
  selectSelectedLayoutTagIds,
  (layouts: LayoutModel[], relations: LayoutTagRelationModel[], tags: string[]): string[] => {
    // console.log(relations);
    if (tags.length === 0) return [];
    return layouts
      .filter((layout) => isLayoutMatches(layout.id, tags, relations))
      .map((layout) => layout.id);
  }
);

export const isLayoutMatches = (
  layoutId: string,
  tags: string[],
  relations: LayoutTagRelationModel[]
): boolean => {
  const tagGroup = tags.reduce<Record<string, string[]>>((acc, val) => {
    const [tagId, tagValue] = val.split(TAG_VALUE_DIVIDER);
    // 空のTaxIDもタグ値として保持する。区切りがなく値が存在しない場合と区別する。
    if (!tagId || tagValue === undefined) throw "Invalid tag format";
    if (!acc[tagId]) acc[tagId] = [];
    acc[tagId].push(tagValue);
    return acc;
  }, {});

  const myRelations = relations
    .filter((relation) => relation.layoutId === layoutId)
    .filter((relation) => {
      const { tagId, tagValue } = relation;
      return tagGroup[tagId]?.includes(tagValue);
    });

  return myRelations.length === Object.keys(tagGroup).length;
};

export const __TEST__selectCurrentLayoutIds = { isLayoutMatches };
