import { CompoundNodeObject } from "@core/canvas/node/CompoundNodeObject";
import { EmptyNodeObject } from "@core/canvas/node/EmptyNodeObject";
import { ProteinNodeObject } from "@core/canvas/node/ProteinNodeObject";
import { ReactionNodeObject } from "@core/canvas/node/ReactionNodeObject";
import { useAppSelector } from "@core/state/hooks";
import { selectCanvasMode } from "@core/state/slices/app/canvasModeSlice";
import { selectGridSize } from "@core/state/slices/app/gridSlice";
import { NodeModel } from "@core/state/slices/entities/nodeModelsSlice";
import React, { FC } from "react";

type Props = {
  model: NodeModel;
};

export const NodeObject: FC<Props> = ({ model }) => {
  const canvasMode = useAppSelector(selectCanvasMode);
  const grid = useAppSelector(selectGridSize);
  if (!model) return;
  switch (model.entityType) {
    case "compound":
    case "subCompound":
      return (
        <CompoundNodeObject
          model={model}
          grid={grid}
          mode={canvasMode}
        />
      );
    case "reaction":
      return (
        <ReactionNodeObject
          model={model}
          grid={grid}
          mode={canvasMode}
        />
      );
    case "protein":
      return (
        <ProteinNodeObject
          model={model}
          grid={grid}
          mode={canvasMode}
        />
      );
    case "empty":
      return (
        <EmptyNodeObject
          model={model}
          grid={grid}
          mode={canvasMode}
        />
      );
    default:
      return <></>;
  }
};
