import { ConnectionsSelectors } from "@core/state/slices/entities/connectionModelsSlice";
import { createSelector } from "@reduxjs/toolkit";

export const selectHasHorizontalConnections = createSelector(
  [ConnectionsSelectors.selectAll, (state, id) => id],
  (connections, id): boolean => {
    return (
      connections
        .filter((connection) => connection.source === id || connection.target === id)
        .filter((connection) => connection.orientation === "horizontal").length > 0
    );
  }
);
