import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { selectTooltipValue, TooltipActions } from "@core/state/slices/app/tooltip";

export const useTooltip = () => {
  const dispatch = useAppDispatch();
  const setTooltipValue = (value: string) => {
    dispatch(TooltipActions.setTooltipValue(value));
  };
  const tooltipValue = useAppSelector(selectTooltipValue);
  return { setTooltipValue, tooltipValue };
};
