import { Checkbox } from "@core/components/mui/Checkbox";
import { CheckboxProps } from "@mui/material";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import React, { FC, PropsWithChildren } from "react";

type Props = {
  title: string;
  checkBoxProps?: CheckboxProps;
} & PropsWithChildren;

export const FieldSet: FC<Props> = ({ title, children, checkBoxProps }) => {
  if (children === undefined || children === "" || children === null) return null;
  return (
    <Stack sx={{ gap: 0.5 }}>
      <Stack
        direction={"row"}
        sx={{ justifyContent: "space-between", alignItems: "flex-end" }}
      >
        <Typography
          variant={"body2"}
          sx={{ lineHeight: 1 }}
        >
          {title}
        </Typography>
        {checkBoxProps && <Checkbox {...checkBoxProps} />}
      </Stack>
      {typeof children === "string" ? (
        <Typography
          sx={{
            borderStyle: "solid",
            borderWidth: "1px",
            paddingInline: 1,
            paddingBlock: 0.5,
            borderRadius: 1,
            borderColor: "rgba(255, 255, 255, 0.10)",
          }}
        >
          {children !== "" ? children : "--"}
        </Typography>
      ) : (
        children
      )}
    </Stack>
  );
};
