import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSelector, createSlice } from "@reduxjs/toolkit";
import { extendZod } from "@schema/extendZod";
import z from "zod";

extendZod();
const schema = z.object({
  id: z.string(),
  tagId: z.string(),
  tagValue: z.string(),
  layoutId: z.string(),
});
export type LayoutTagRelationModel = z.infer<typeof schema>;

const adapter = createEntityAdapter<LayoutTagRelationModel, string>({
  selectId: (layoutTagRelation) => layoutTagRelation.id,
});

const slice = createSlice({
  name: "entities/layoutTagRelations",
  initialState: adapter.getInitialState(),
  reducers: {
    addLayoutTagRelation: adapter.addOne,
    updateLayoutTagRelation: adapter.updateOne,
    removeLayoutTagRelation: adapter.removeOne,
    removeLayoutTagRelations: adapter.removeMany,
    removeAllLayoutTagRelations: adapter.removeAll,
    setLayoutTagRelations: adapter.setAll,
    upsertLayoutTagRelation: adapter.upsertOne,
    upsertLayoutTagRelations: adapter.upsertMany,
    addLayoutTagRelations: adapter.addMany,
    updateLayoutTagRelations: adapter.updateMany,
  },
});

export const layoutTagRelationsReducer = slice.reducer;
export const LayoutTagRelationsActions = slice.actions;

const selectors = adapter.getSelectors<CommonState>((state) => state.entities.layoutTagRelations);
const selectRelationsByLayoutId = createSelector(
  [selectors.selectAll, (state: CommonState, layoutId: string) => layoutId],
  (relations, layoutId) => relations.filter((relation) => relation.layoutId === layoutId)
);
export const LayoutTagRelationSelectors = { ...selectors, selectRelationsByLayoutId };
