import { useAppSelector } from "@core/state/hooks";
import { selectErrorCount, selectRecentError } from "@core/state/slices/errorLogSlice";
import { Alert, Snackbar } from "@mui/material";
import { useEffect, useState } from "react";

export const AppSnackBar = () => {
  const errorCount = useAppSelector(selectErrorCount);
  const errorMessage = useAppSelector(selectRecentError);

  const [open, setOpen] = useState(false);

  const handleClose = () => {
    setOpen(false);
  };

  // TODO: 新しいエラーで再表示する挙動を保ち、閉じた時点の件数から表示状態を導く方式を検討する。
  useEffect(() => {
    if (errorCount === 0) return;
    // oxlint-disable-next-line react/set-state-in-effect -- エラー件数の変化で通知を開く既存動作を当面維持する。
    setOpen(true);
  }, [errorCount]);

  return (
    <Snackbar open={open}>
      <Alert
        severity={"error"}
        onClick={handleClose}
      >
        {errorMessage}
      </Alert>
    </Snackbar>
  );
};
