import { createSelector, createSlice } from "@reduxjs/toolkit";
import type { RootState } from "@viewer/state/store";

type SelectionItem = {
  id: string;
  label: string;
};
type State = {
  selectedPathways: SelectionItem[];
  selectedTaxons: SelectionItem[];
};

const initialState: State = {
  selectedPathways: [],
  selectedTaxons: [],
};

const slice = createSlice({
  name: "viewer/browserSelection",
  initialState,
  reducers: {
    setPathwaySelection(state, action: { payload: SelectionItem }) {
      state.selectedPathways = toggleSelection(state.selectedPathways, action.payload);
    },
    clearPathwaySelection(state) {
      state.selectedPathways = [];
    },
    mergeTaxonSelection(state, action: { payload: SelectionItem }) {
      state.selectedTaxons = mergeSelection(state.selectedTaxons, action.payload);
    },
    clearTaxonSelection(state) {
      state.selectedTaxons = [];
    },
    clearAllSelections(state) {
      state.selectedPathways = [];
      state.selectedTaxons = [];
    },
  },
});

export const BrowserSelectionActions = slice.actions;
export const browserSelectionReducer = slice.reducer;

const selectState = (state: RootState) => state.viewer.browser;
export const selectBrowserPathwaySelection = createSelector(selectState, (s) => s.selectedPathways);
export const selectBrowserTaxonSelection = createSelector(selectState, (s) => s.selectedTaxons);

const toggleSelection = (prev: SelectionItem[], item: SelectionItem) => {
  return prev.find((p) => p.id === item.id) ? [] : [item];
};

const mergeSelection = (prev: SelectionItem[], item: SelectionItem) => {
  const index = prev.findIndex((t) => t.id === item.id);
  if (index >= 0) {
    return [...prev.slice(0, index), ...prev.slice(index + 1)];
  }
  return [...prev, item];
};

export const __TEST__browserSelectionSlice = {
  mergeSelection,
  toggleSelection,
};
