import { appDataSchema } from "@schema/app/AppData";
import { z } from "zod";

export type ImportValidationResult = { errors: string[]; warnings: string[] };

// 現行スキーマのオブジェクト・配列・再帰・任意項目をたどり、未定義のキーを検出する。
// 検証に失敗した入力でも警告を併記できるよう、成功後のデータとの差分には依存しない。
const collectWarnings = (schema: unknown, value: unknown, path: string): string[] => {
  if (schema instanceof z.ZodOptional || schema instanceof z.ZodLazy) {
    return collectWarnings(schema.unwrap(), value, path);
  }
  if (schema instanceof z.ZodArray && Array.isArray(value)) {
    return value.flatMap((item, index) =>
      collectWarnings(schema.element, item, `${path}[${index}]`)
    );
  }
  if (value === null || typeof value !== "object" || Array.isArray(value)) return [];
  if (schema instanceof z.ZodRecord) {
    return Object.entries(value).flatMap(([key, item]) =>
      collectWarnings(schema.valueType, item, `${path}.${key}`)
    );
  }
  if (!(schema instanceof z.ZodObject)) return [];
  return Object.entries(value).flatMap(([key, item]) => {
    const itemPath = `${path}.${key}`;
    if (!Object.prototype.hasOwnProperty.call(schema.shape, key)) {
      return [`${itemPath}: Undefined field; it will be removed during import.`];
    }
    return collectWarnings(schema.shape[key], item, itemPath);
  });
};

// 取り込みやストア更新をせず、入力の構文とAPIスキーマだけを検証する。
export const validateImportJson = (json: string): ImportValidationResult => {
  if (json.trim() === "") return { errors: ["Please enter JSON data."], warnings: [] };
  let data: unknown;
  try {
    data = JSON.parse(json);
  } catch (error) {
    return {
      errors: [`Invalid JSON: ${error instanceof Error ? error.message : "Syntax error"}`],
      warnings: [],
    };
  }
  const result = appDataSchema.safeParse(data);
  const warnings = collectWarnings(appDataSchema, data, "$");
  if (result.success) return { errors: [], warnings };
  const errors = result.error.issues.map((issue) => {
    const path = issue.path.reduce<string>(
      (text, part) => (typeof part === "number" ? `${text}[${part}]` : `${text}.${String(part)}`),
      "$"
    );
    return `${path}: ${issue.message}`;
  });
  return { errors, warnings };
};
