import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSlice } from "@reduxjs/toolkit";
import { layoutTagDataSchema } from "@schema/app/LayoutTagData";
import z from "zod";

const schema = layoutTagDataSchema.omit({ values: true });

export type LayoutTagModel = z.infer<typeof schema>;

const adapter = createEntityAdapter<LayoutTagModel, string>({
  selectId: (layoutTag) => layoutTag.id,
});

const slice = createSlice({
  name: "entities/layoutTags",
  initialState: adapter.getInitialState(),
  reducers: {
    addLayoutTag: adapter.addOne,
    updateLayoutTag: adapter.updateOne,
    upsertLayoutTag: adapter.upsertOne,
    removeLayoutTag: adapter.removeOne,
    addLayoutTags: adapter.addMany,
    updateLayoutTags: adapter.updateMany,
    upsertLayoutTags: adapter.upsertMany,
    removeLayoutTags: adapter.removeMany,
    setLayoutTags: adapter.setAll,
    removeAllLayoutTags: adapter.removeAll,
  },
});

export const layoutTagReducer = slice.reducer;
export const LayoutTagActions = slice.actions;
export const LayoutTagSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.layoutTags
);
