import { ScrollWrapper } from "@core/components/atoms/ScrollWrapper";
import { Tab, Tabs } from "@core/components/mui/Tabs";
import Box from "@mui/material/Box";
import { DocumentPane } from "@viewer/propertyPanel/pane/DocumentPane";
import { InfoPane } from "@viewer/propertyPanel/pane/InfoPane";
import { PathwayPane } from "@viewer/propertyPanel/pane/PathwayPane";
import { ViewSettingsPane } from "@viewer/propertyPanel/pane/ViewSettingsPane";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import {
  GeneralPanelTabId,
  generalPanelTabIds,
  selectGeneralTabId,
  ViewerTabActions,
} from "@viewer/state/slices/tabSlice";
import React, { FC, SyntheticEvent } from "react";

type Props = {};

export const GeneralPanel: FC<Props> = ({}) => {
  const currentTabId = useAppSelector(selectGeneralTabId);
  const dispatch = useAppDispatch();

  const handleTabChange = (e: SyntheticEvent, key: GeneralPanelTabId) => {
    dispatch(ViewerTabActions.setGeneralTab(key));
  };
  return (
    <Box sx={{ height: "100%", overflow: "hidden", display: "flex", flexDirection: "column" }}>
      <Tabs
        value={currentTabId}
        onChange={handleTabChange}
        variant="fullWidth"
        sx={{ "& .MuiTab-root": { minWidth: 0 } }}
      >
        <Tab
          value={generalPanelTabIds.document}
          label={"Document"}
        />
        <Tab
          value={generalPanelTabIds.pathway}
          label={"Pathway"}
        />
        <Tab
          value={generalPanelTabIds.view}
          label={"View"}
        />
        <Tab
          value={generalPanelTabIds.info}
          label={"Info"}
        />
      </Tabs>
      <ScrollWrapper>
        {currentTabId === generalPanelTabIds.document && <DocumentPane />}
        {currentTabId === generalPanelTabIds.pathway && <PathwayPane />}
        {currentTabId === generalPanelTabIds.view && <ViewSettingsPane />}
        {currentTabId === generalPanelTabIds.info && <InfoPane />}
      </ScrollWrapper>
    </Box>
  );
};
