import Stack from "@mui/material/Stack";
import { useProteinPanel } from "@viewer/hooks/useProteinPanel";
import { FieldSet } from "@viewer/propertyPanel/sub/FieldSet";
import { ReferenceList } from "@viewer/propertyPanel/sub/ReferenceList";
import React, { FC } from "react";

type Props = { id: string; parentId?: string };

export const SimpleProteinPane: FC<Props> = ({ id, parentId }) => {
  const { currentLabel, protein, reaction, handleCheckLabel } = useProteinPanel(id);
  return (
    <Stack spacing={1.5}>
      <FieldSet
        title={"Name"}
        checkBoxProps={
          !parentId
            ? {
                checked: currentLabel === "name",
                onClick: () => handleCheckLabel("name"),
              }
            : undefined
        }
      >
        {protein.name}
      </FieldSet>
      <FieldSet title={"Synonym"}>{protein.synonym}</FieldSet>
      <FieldSet
        title={"Gene name"}
        checkBoxProps={
          !parentId
            ? {
                checked: currentLabel === "geneName",
                onClick: () => handleCheckLabel("geneName"),
              }
            : undefined
        }
      >
        {protein.geneName}
      </FieldSet>

      {!parentId && (
        <>
          <FieldSet
            title={"Reaction name"}
            checkBoxProps={{
              checked: currentLabel === "reactionName",
              onClick: () => handleCheckLabel("reactionName"),
            }}
          >
            {reaction?.name}
          </FieldSet>
          <FieldSet
            title={"Enzyme code"}
            checkBoxProps={{
              checked: currentLabel === "enzymeCode",
              onClick: () => handleCheckLabel("enzymeCode"),
            }}
          >
            {reaction?.enzymeCode}
          </FieldSet>
        </>
      )}
      <FieldSet title={"Description"}>{protein.description}</FieldSet>
      <ReferenceList parentId={id} />
    </Stack>
  );
};
