import { ReactionElement } from "@core/canvas/elements/ReactionElement";
import { composeNodeElementProps, NodeObjProps } from "@core/canvas/node/types";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { useIsItemSelected } from "@core/state/hooks/useIsItemSelected";
import { selectHasHorizontalConnections } from "@core/state/selectors/selectHasHorizontalConnections";
import { selectReactionLabelKey } from "@core/state/slices/app/labelKeySlice";
import { ItemSelectionActions } from "@core/state/slices/app/selection/itemSelection";
import { ReactionsSelectors } from "@core/state/slices/entities/reactionModelsSlice";
import React, { FC } from "react";

export const ReactionNodeObject: FC<NodeObjProps> = ({ model, grid }) => {
  const dispatch = useAppDispatch();
  const labelKey = useAppSelector(selectReactionLabelKey);
  const entity = useAppSelector((state) => ReactionsSelectors.selectById(state, model.entityId));
  const isSelected = useIsItemSelected(model.id);
  const hasHorizontal = useAppSelector((state) => selectHasHorizontalConnections(state, model.id));
  const placement = hasHorizontal ? "bottom" : "right";
  const onSelect = () => {
    dispatch(ItemSelectionActions.setSelectedItemId(model.id));
  };
  if (!entity) return <></>;
  const label: string = labelKey ? (entity[labelKey] ?? "--") : "";
  return (
    <ReactionElement
      {...composeNodeElementProps(model, grid, label, isSelected, onSelect)}
      placement={placement}
    />
  );
};
