import { Sheet } from "@core/components/mui/Sheet";
import { useAppSelector } from "@core/state/hooks";
import { LayoutTagSelectors } from "@core/state/slices/entities/layoutTagModelSlice";
import { DocumentList } from "@viewer/propertyPanel/sub/DocumentList";
import { LayoutList } from "@viewer/propertyPanel/sub/LayoutList";
import React, { FC } from "react";

type Props = {};

export const PathwayPane: FC<Props> = ({}) => {
  const layoutTags = useAppSelector(LayoutTagSelectors.selectAll);
  return (
    <Sheet
      sx={{ maxHeight: "max-content", p: 2, display: "flex", flexDirection: "column", gap: 2 }}
    >
      {layoutTags.map((layoutTag, index) => (
        <LayoutList
          tag={layoutTag}
          key={layoutTag.id}
        />
      ))}

      {/*<DocumentList />*/}
    </Sheet>
  );
};
