import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSlice } from "@reduxjs/toolkit";
import { ProteinData } from "@schema/app/ProtainData";
import { nanoid } from "nanoid";

export type ProteinModel = Omit<ProteinData, "references" | "oneOf" | "allOf"> & {
  oneOf?: string[];
  allOf?: string[];
};

export type ProteinLabel =
  | null
  | keyof Omit<ProteinModel, "id" | "description" | "oneOf" | "allOf" | "synonym">
  | "enzymeCode"
  | "reactionName";

const adapter = createEntityAdapter<ProteinModel, string>({
  selectId: (protein) => protein.id,
  sortComparer: (a, b) => (a.name ?? "").localeCompare(b.name ?? ""),
});

const slice = createSlice({
  name: "entities/proteins",
  initialState: adapter.getInitialState(),
  reducers: {
    addProtein: adapter.addOne,
    updateProtein: adapter.updateOne,
    upsertProtein: adapter.upsertOne,
    removeProtein: adapter.removeOne,
    addProteins: adapter.addMany,
    updateProteins: adapter.updateMany,
    upsertProteins: adapter.upsertMany,
    removeProteins: adapter.removeMany,
    setProteins: adapter.setAll,
    removeAllProteins: adapter.removeAll,
  },
});

export const proteinsReducer = slice.reducer;
export const ProteinsActions = slice.actions;
export const ProteinsSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.proteins
);

export const createNewProtein = (): ProteinModel => ({
  id: nanoid(),
  reactionId: "",
  name: "",
  description: "",
  geneName: "",
  organism: "",
  taxId: "",
});
