import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";
import type { RootState } from "@viewer/state/store";

type state = {
  specificDataUrl: string;
  taxIds: string[];
  variantId: string;
};

const initialState: state = {
  specificDataUrl: "",
  taxIds: [],
  variantId: "",
};

const slice = createSlice({
  name: "viewer/currentDocument",
  initialState,
  reducers: {
    setSpecificDataUrl(state, payload: PayloadAction<string>) {
      state.specificDataUrl = payload.payload;
    },
    setTaxIds(state, payload: PayloadAction<string[]>) {
      state.taxIds = payload.payload;
    },
    setVariantId(state, payload: PayloadAction<string>) {
      state.variantId = payload.payload;
    },
  },
});

export const currentViewerDocumentReducer = slice.reducer;
export const CurrentViewerDocumentActions = slice.actions;

const selectState = (state: RootState) => state.viewer.currentDocument;
export const selectCurrentViewerSpecificDataUrl = createSelector(
  selectState,
  (s) => s.specificDataUrl
);
/**
 * @deprecated
 */
export const selectCurrentViewerTaxIds = createSelector(selectState, (s) => s.taxIds);
/**
 * @deprecated
 */
export const selectCurrentViewerVariantId = createSelector(selectState, (s) => s.variantId);
//
export const selectDataUrls = createSelector(selectState, (s) => {
  if (s.specificDataUrl) {
    return [s.specificDataUrl];
  }
  if (s.variantId.length > 0 && s.taxIds.length > 0) {
    return s.taxIds.map(
      (taxId) => `https://dev.togomedium.org/pathway_data/${s.variantId}_var_1/${taxId}.json`
    );
  }
  return [];
});
