import { ConnectionObject } from "@core/canvas/ConnectionObject";
import { NodeObject } from "@core/canvas/node/NodeObject";
import { useAppSelector } from "@core/state/hooks";
import { ConnectionsSelectors } from "@core/state/slices/entities/connectionModelsSlice";
import { NodesSelectors } from "@core/state/slices/entities/nodeModelsSlice";
import { PathwayFrame } from "@viewer/canvas/PathwayFrame";
import React, { FC, useLayoutEffect } from "react";

type Props = {
  layoutId: string;
  x: number;
  y: number;
};

export const PathwayGraph: FC<Props> = ({ layoutId, x, y }) => {
  const connections = useAppSelector((state) =>
    ConnectionsSelectors.selectByLayoutId(state, layoutId)
  );
  const nodes = useAppSelector((state) => NodesSelectors.selectByLayoutId(state, layoutId));

  return (
    <PathwayFrame
      layoutId={layoutId}
      x={x}
      y={y}
    >
      <g>
        {connections.map((d) => (
          <ConnectionObject
            key={d.id}
            model={d}
          />
        ))}
      </g>
      <g>
        {nodes.map((d) => (
          <NodeObject
            key={d.id}
            model={d}
          />
        ))}
      </g>
    </PathwayFrame>
  );
};
