import { ImportDialog } from "@core/modal/ImportDialog";
import { useModal } from "@core/state/hooks/useModal";
import { importDataFromJson } from "@core/state/utils/import";
import { validateImportJson } from "@core/state/utils/validateImportJson";
import { useAppDispatch } from "@viewer/state/hooks";
import { ViewerPanelActions } from "@viewer/state/slices/panelSlice";
import { FC } from "react";

export const ImportModal: FC = () => {
  const { closeModal, isModalOpen } = useModal();
  const dispatch = useAppDispatch();
  const onSubmit = (json: string) => {
    dispatch(importDataFromJson(json));
    // モーダル内の事前検証を通った入力を取り込む。
    closeModal();
    dispatch(ViewerPanelActions.closeBrowserPanel());
  };

  return (
    <ImportDialog
      open={isModalOpen}
      onClose={closeModal}
      onSubmit={onSubmit}
      onValidate={validateImportJson}
    />
  );
};
