export const entityTypes = ["compound", "reaction", "protein", "empty", "subCompound"] as const;
export type EntityType = (typeof entityTypes)[number];

export const pathOrientations = ["horizontal", "vertical"] as const;
export type PathOrientation = (typeof pathOrientations)[number];

export const pathShapes = [
  "direct",
  "doubleRightAngles",
  "rightAngle",
  "loop",
  "doubleLine",
] as const;
export type PathShape = (typeof pathShapes)[number];
