import type { CommonState } from "@core/state/common";
import { createSelector, createSlice } from "@reduxjs/toolkit";

type State = {
  id: string | null;
};

const initialState: State = {
  id: null,
};

const slice = createSlice({
  name: "app/selections/item",
  initialState,
  reducers: {
    setSelectedItemId: (state, action) => {
      state.id = action.payload;
    },
    clearItemSelection: (state) => {
      state.id = null;
    },
  },
});

export const ItemSelectionActions = slice.actions;
export const itemSelectionReducer = slice.reducer;

const selectState = (state: CommonState) => state.app.selections.selectedItem;
export const selectSelectedItemId = createSelector(selectState, (s) => s.id);
