import React from "react";
import ReactDOM from "react-dom";
import { createRoot } from "react-dom/client";
import Stanza from "togostanza/stanza";

const importWebFont = (stanza: Stanza) => {
  stanza.importWebFontCSS(
    `https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;700&family=Roboto:wght@400;700&family=Roboto+Condensed:wght@100..900&display=swap`
  );
};

export abstract class ReactStanza<T> extends Stanza {
  reactElm = this.root.querySelector("main")!;
  reactRoot = createRoot(this.reactElm as HTMLElement);
  abstract makeApp(): React.ReactElement;
  async render() {
    this._render();
    importWebFont(this);
  }

  handleAttributeChange() {
    this._render();
  }
  _render() {
    const children = this.makeApp();
    const main = this.reactElm;
    this.reactRoot.render(<>{children}</>);
    // const wrapper = main.parentElement!;
    // //
    // const height = this.params["height"];
    // if (height) {
    //   wrapper.style.transform = "scale(1)";
    //   wrapper.style.overflow = "clip";
    // } else {
    //   wrapper.style.display = "contents";
    //   main.style.display = "contents";
    // }
  }
}
