import { isValidShape } from "@core/utils/svg";
import React, { FC, useMemo } from "react";

type Props = {
  width?: number;
  height?: number;
  x: number;
  y: number;
  fontSize?: number;
  label: string;
  textAlign?: "center" | "left" | "right";
  color?: string;
  backgroundColor?: string;
  padding?: string;
  onClick?: () => void;
};

export const ClippableText: FC<Props> = ({
  width = 100,
  height,
  x,
  y,
  label,
  fontSize = 12,
  textAlign = "center",
  color = "#000000",
  backgroundColor = "#FFFFFF",
  padding = "0",
  onClick,
}) => {
  const posX = useMemo(() => {
    switch (textAlign) {
      case "center":
        return x - width / 2;
      case "right":
        return x - width;
      default:
        return x;
    }
  }, [width, textAlign, x]);
  const marginInline = useMemo(() => {
    switch (textAlign) {
      case "center":
        return "auto";
      case "right":
        return "auto 0";
      case "left":
        return "0 auto";
    }
  }, [textAlign]);
  if (!isValidShape(x, y, width)) {
    return null;
  }
  return (
    <foreignObject
      x={posX}
      y={y}
      width={width}
      height={height ?? fontSize * 1.5}
      requiredExtensions="http://www.w3.org/1999/xhtml"
    >
      <p
        style={{
          fontFamily: `"Roboto Condensed", sans-serif`,
          maxWidth: "100%",
          width: "fit-content",
          marginInline: `${marginInline}`,
          textAlign: `${textAlign}`,
          lineHeight: "1.1",
          fontSize: `${fontSize}px`,
          fontWeight: "400",
          whiteSpace: "nowrap",
          textOverflow: "ellipsis",
          overflow: "hidden",
          userSelect: "none",
          boxSizing: "border-box",
          backgroundColor: `${backgroundColor}`,
          color: `${color}`,
          padding: `${padding}`,
          cursor: onClick ? "pointer" : "default",
          pointerEvents: onClick ? "auto" : "none",
        }}
        onClick={onClick}
      >
        {label}
      </p>
    </foreignObject>
  );
};
