import { connectionDataSchema } from "@schema/app/ConnectionData";
import { nodeDataSchema } from "@schema/app/NodeData";
import { referenceDataSchema } from "@schema/app/ReferenceData";
import { extendZod } from "@schema/extendZod";
import z from "zod";

extendZod();

export const layoutDataSchema = z.object({
  id: z.string().optional(),
  name: z.string(),
  tags: z.record(z.string(), z.string()).openapi({
    example: {
      mode: "reaction",
      prediction: "predicted",
    },
  }),
  description: z.string().optional(),
  references: z.array(referenceDataSchema).optional(),
  nodes: z.array(nodeDataSchema),
  connections: z.array(connectionDataSchema),
});

export type LayoutData = z.infer<typeof layoutDataSchema>;
