import { ColorArg } from "@core/types";
import { PathOrientation, PathShape } from "@schema/app/enums";
import { colord } from "colord";
import React, { FC, useMemo } from "react";

type Props = {
  ax: number;
  ay: number;
  bx: number;
  by: number;
  r?: number;
  loopMod?: number;
  color?: ColorArg;
  strokeWidth?: number;
  shape?: PathShape;
  orientation?: PathOrientation;
  strokeDasharray?: number[];
  markerStart?: string;
  markerEnd?: string;
};
export const Path: FC<Props> = ({
  ax,
  ay,
  bx,
  by,
  r = 10,
  loopMod = 75,
  color = "#000000",
  strokeWidth = 1,
  orientation = "horizontal",
  shape,
  strokeDasharray = [],
  markerStart,
  markerEnd,
}) => {
  const path = useMemo(() => {
    switch (shape) {
      case "doubleRightAngles":
        return makeDoubleRightAnglesPath(ax, ay, bx, by, r, orientation);
      case "rightAngle":
        return makeRightAnglePath(ax, ay, bx, by, r, orientation);
      case "loop":
        return makeLoopPath(ax, ay, bx, by, r, orientation, loopMod);
      default:
        return makeDirectPath(ax, ay, bx, by);
    }
  }, [shape, orientation, ax, ay, bx, by, r, loopMod]);
  return (
    <path
      d={path}
      stroke={color && colord(color).toHex()}
      strokeWidth={strokeWidth}
      fill={"none"}
      strokeDasharray={strokeDasharray.join(" ")}
      {...(markerStart && { markerStart: `url(#${markerStart})` })}
      {...(markerEnd && { markerEnd: `url(#${markerEnd})` })}
    />
  );
};

// 0.447715 is a magic number for rounded corners;
// https://stackoverflow.com/questions/1734745/how-to-create-circle-with-b%C3%A9zier-curves
const ROUNDED_CORNER_RATIO = 0.447715;

const makeDirectPath = (ax: number, ay: number, bx: number, by: number) => {
  return `M ${ax} ${ay} L ${bx} ${by}`;
};

const makeLoopPath = (
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number = 10,
  orientation: PathOrientation,
  m: number
) => {
  const mx = m > 0 ? Math.max(ax, bx) + m : Math.min(ax, bx) + m;
  const my = m > 0 ? Math.max(ay, by) + m : Math.min(ay, by) + m;
  if (Math.abs(m) < r) {
    if (orientation === "vertical") {
      return `M ${ax} ${ay} L ${ax} ${my} L ${bx} ${my} L ${bx} ${by}`;
    } else {
      return `M ${ax} ${ay} L ${mx} ${ay} L ${mx} ${by} L ${bx} ${by}`;
    }
  } else {
    const c = ROUNDED_CORNER_RATIO * r;
    if (orientation === "vertical") {
      const hd = m > 0 ? 1 : -1;
      const vd = by - ay > 0 ? 1 : -1;
      return `
      M ${ax} ${ay}
      L ${mx - r * hd} ${ay}
      C ${mx + (c - r) * hd} ${ay} ${mx} ${ay - (c - r) * vd} ${mx} ${ay + r * vd}
      L ${mx} ${by - r * vd}
      C ${mx} ${by + (c - r) * vd} ${mx + (c - r) * hd} ${by} ${mx - r * hd} ${by}
      L ${bx} ${by}`;
    } else {
      const hd = bx - ax > 0 ? 1 : -1;
      const vd = m > 0 ? 1 : -1;
      return `
      M ${ax} ${ay}
      L ${ax} ${my - r * vd}
      C ${ax} ${my + (c - r) * vd} ${ax - (c - r) * hd} ${my} ${ax + r * hd} ${my}
      L ${ax + r * hd} ${my}
      L ${bx - r * hd} ${my}
      C ${bx + (c - r) * hd} ${my} ${bx} ${my + (c - r) * vd} ${bx} ${my - r * vd} 
      L ${bx} ${by}`;
    }
  }
};

const makeRightAnglePath = (
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number = 10,
  orientation: PathOrientation
) => {
  const h = Math.min(Math.abs(by - ay), Math.abs(bx - ax));
  if (h < r) {
    if (orientation === "horizontal") {
      return `M ${ax} ${ay} L ${ax} ${by} L ${bx} ${by}`;
    } else {
      return `M ${ax} ${ay} L ${bx} ${ay} L ${bx} ${by}`;
    }
  } else {
    const c = ROUNDED_CORNER_RATIO * r;
    const hd = bx - ax > 0 ? 1 : -1;
    const vd = by - ay > 0 ? 1 : -1;
    if (orientation === "horizontal") {
      return `
      M ${ax} ${ay}
      L ${bx - r * hd} ${ay}
      C ${bx + (c - r) * hd} ${ay} ${bx} ${ay + (r - c) * vd} ${bx} ${ay + r * vd}
      L ${bx} ${by}`;
    } else {
      return `
      M ${ax} ${ay}
      L ${ax} ${by - r * vd}
      C ${ax} ${by + (c - r) * vd} ${ax - (c - r) * hd} ${by} ${ax + r * hd} ${by}
      L ${bx} ${by}`;
    }
  }
};

const makeDoubleRightAnglesPath = (
  ax: number,
  ay: number,
  bx: number,
  by: number,
  r: number = 10,
  orientation: PathOrientation
) => {
  const mx = ax + (bx - ax) / 2;
  const my = ay + (by - ay) / 2;
  const h = Math.min(Math.abs(by - ay), Math.abs(bx - ax));
  if (h <= r * 2) {
    if (orientation === "horizontal") {
      return `M ${ax} ${ay} L ${mx} ${ay} L ${mx} ${by} L ${bx} ${by}`;
    } else {
      return `M ${ax} ${ay} L ${ax} ${my} L ${bx} ${my} L ${bx} ${by}`;
    }
  }

  const c = ROUNDED_CORNER_RATIO * r;
  //HorizontalDirection / VerticalDirection
  const hd = bx - ax > 0 ? 1 : -1;
  const vd = by - ay > 0 ? 1 : -1;
  if (orientation === "horizontal") {
    return `
    M ${ax} ${ay}
    L ${mx - r * hd} ${ay}
    C ${mx + (c - r) * hd} ${ay} ${mx} ${ay + (r - c) * vd} ${mx} ${ay + r * vd}
    L ${mx} ${by - r * vd}
    C ${mx} ${by + (c - r) * vd} ${mx + (r - c) * hd} ${by} ${mx + r * hd} ${by}
    L ${bx} ${by}`;
  } else {
    return `
    M ${ax} ${ay}
    L ${ax} ${my - r * vd}
    C ${ax} ${my + (c - r) * vd} ${ax + (r - c) * hd} ${my} ${ax + r * hd} ${my}
    L ${bx - r * hd} ${my}
    C ${bx + (c - r) * hd} ${my} ${bx} ${my + (r - c) * vd} ${bx} ${my + r * vd}
    L ${bx} ${by}`;
  }
};
