import type { CommonState } from "@core/state/common";
import { createSelector, createSlice, PayloadAction } from "@reduxjs/toolkit";

type State = {
  value: string;
};
const initialState: State = {
  value: "",
};

const slice = createSlice({
  name: "app/tooltip",
  initialState,
  reducers: {
    setTooltipValue(state, action: PayloadAction<string>) {
      state.value = action.payload;
    },
  },
});

export const tooltipReducer = slice.reducer;
export const TooltipActions = slice.actions;

const selectState = (state: CommonState) => state.app.tooltip;
export const selectTooltipValue = createSelector(selectState, (s) => s.value);
