import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSlice } from "@reduxjs/toolkit";
import { layoutDataSchema } from "@schema/app/LayoutData";
import { extendZod } from "@schema/extendZod";
import { nanoid } from "nanoid";
import z from "zod";

extendZod();
const schema = layoutDataSchema
  .omit({
    references: true,
    nodes: true,
    connections: true,
    tags: true,
    id: true,
  })
  .extend({
    id: z.string(),
    documentId: z.string(),
  });

export type LayoutModel = z.infer<typeof schema>;

const adapter = createEntityAdapter<LayoutModel, string>({
  selectId: (layout) => layout.id,
});

const slice = createSlice({
  name: "entities/layouts",
  initialState: adapter.getInitialState(),
  reducers: {
    addLayout: adapter.addOne,
    updateLayout: adapter.updateOne,
    removeLayout: adapter.removeOne,
    removeLayouts: adapter.removeMany,
    removeAllLayouts: adapter.removeAll,
    setLayouts: adapter.setAll,
    upsertLayout: adapter.upsertOne,
    upsertLayouts: adapter.upsertMany,
    addLayouts: adapter.addMany,
    updateLayouts: adapter.updateMany,
  },
});

export const layoutsReducer = slice.reducer;
export const LayoutsActions = slice.actions;
export const LayoutsSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.layouts
);

export const createNewLayoutEntity = (): LayoutModel => {
  const id = nanoid();
  return {
    id,
    name: "New layout",
    description: "",
    // TODO: documentId should be set to the current documentId
    documentId: "",
  };
};
