import { Circle } from "@core/canvas/atoms/Circle";
import { COLOR_SELECTED } from "@core/consts";
import { CanvasMode } from "@core/state/slices/app/canvasModeSlice";
import { NodeElementProps } from "@core/types";
import React, { FC } from "react";

export const EMPTY_RADIUS = 4;
type Props = NodeElementProps & { mode: CanvasMode };
export type EmptyNodeData = Props;

export const EmptyElement: FC<Props> = ({ mode, x, y, clickFn, isSelected }) => {
  if (mode === "view") {
    return <></>;
  }
  return (
    <g
      onClick={clickFn}
      style={clickFn && { cursor: "pointer", pointerEvents: "auto" }}
    >
      <Circle
        radius={EMPTY_RADIUS}
        x={x}
        y={y}
        fillColor={"#000000"}
        strokeColor={"#000000"}
        strokeWidth={1.5}
      />
      {isSelected && (
        <rect
          x={x - EMPTY_RADIUS - 2}
          y={y - EMPTY_RADIUS - 2}
          width={EMPTY_RADIUS * 2 + 4}
          height={EMPTY_RADIUS * 2 + 4}
          fill={"transparent"}
          stroke={COLOR_SELECTED}
          strokeWidth={2}
        />
      )}
    </g>
  );
};
