import type { CommonState } from "@core/state/common";
import { selectSelectedItemId } from "@core/state/slices/app/selection/itemSelection";
import { ConnectionsSelectors } from "@core/state/slices/entities/connectionModelsSlice";
import { DocumentsSelectors } from "@core/state/slices/entities/documentModelsSlice";
import { NodesSelectors } from "@core/state/slices/entities/nodeModelsSlice";
import { CanvasSelectionType } from "@core/types";
import { createSelector } from "@reduxjs/toolkit";

export const selectSelectedItemType = createSelector(
  [(state: CommonState) => state, selectSelectedItemId],
  (state, selectedItemId): CanvasSelectionType => {
    if (selectedItemId == null) return "none";
    const id = selectedItemId;
    //
    if (NodesSelectors.selectById(state, id) !== undefined) return "node";
    if (ConnectionsSelectors.selectById(state, id) !== undefined) return "connection";
    if (DocumentsSelectors.selectById(state, id) !== undefined) return "document";
    //
    return "none";
  }
);
