import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSlice } from "@reduxjs/toolkit";
import { CompoundData } from "@schema/app/CompoundData";
import { nanoid } from "nanoid";

export type CompoundModel = Omit<CompoundData, "references">;
export type CompoundLabel = null | keyof Omit<CompoundModel, "id" | "description" | "synonym">;

const adapter = createEntityAdapter<CompoundModel, string>({
  selectId: (compound) => compound.id,
  sortComparer: (a, b) => a.formula.localeCompare(b.formula),
});

const slice = createSlice({
  name: "entities/compounds",
  initialState: adapter.getInitialState(),
  reducers: {
    addCompound: adapter.addOne,
    updateCompound: adapter.updateOne,
    upsertCompound: adapter.upsertOne,
    removeCompound: adapter.removeOne,
    addCompounds: adapter.addMany,
    updateCompounds: adapter.updateMany,
    upsertCompounds: adapter.upsertMany,
    removeCompounds: adapter.removeMany,
    setCompounds: adapter.setAll,
    removeAllCompounds: adapter.removeAll,
  },
});

export const compoundsReducer = slice.reducer;
export const CompoundsActions = slice.actions;

export const CompoundsSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.compounds
);

export const createNewCompound = (): CompoundModel => ({
  id: nanoid(),
  name: "",
  description: "",
  formula: "",
});
