import { pathOrientations, pathShapes } from "@schema/app/enums";
import { extendZod } from "@schema/extendZod";
import z from "zod";

extendZod();

export const connectionDataSchema = z
  .object({
    id: z.string(),
    source: z.string().meta({ description: "起点となる `NodeData.id`" }),
    target: z.string().meta({ description: "終点となる `NodeData.id`" }),
    markerSource: z.boolean().meta({ description: "起点の矢印を表示するかどうか" }),
    markerTarget: z.boolean().meta({ description: "終点の矢印を表示するかどうか" }),
    shape: z.enum(pathShapes),
    orientation: z.enum(pathOrientations),
    strokeColor: z.string().optional(),
    loopMod: z.number().optional().meta({ description: "ループの際の辺の位置。デフォルトは1" }),
    style: z.enum(["solid", "dashed1", "dotted"]).optional(),
  })
  .openapi("ConnectionData");
export type ConnectionData = z.infer<typeof connectionDataSchema>;
