import { Point } from "@core/types";
import { degreeToRadian } from "yohak-tools";

export const findTriangleVertices = (
  vert1: Point,
  height: number,
  angle: number,
  direction: number
): [Point, Point] => {
  direction = direction += 90;
  const { x: x1, y: y1 } = vert1;
  const base = height / Math.tan(degreeToRadian(angle / 2));
  const centerX = x1 + base * Math.cos(degreeToRadian(direction));
  const centerY = y1 + base * Math.sin(degreeToRadian(direction));
  const x2 = centerX + height * Math.cos(degreeToRadian(direction + 90));
  const y2 = centerY + height * Math.sin(degreeToRadian(direction + 90));
  const x3 = centerX + height * Math.cos(degreeToRadian(direction - 90));
  const y3 = centerY + height * Math.sin(degreeToRadian(direction - 90));
  const vert2 = { x: x2, y: y2 };
  const vert3 = { x: x3, y: y3 };
  return [vert2, vert3];
};
