import { data4 } from "@core/data/data4";
import { data5 } from "@core/data/data5";
import { useModal } from "@core/state/hooks/useModal";
import { importData } from "@core/state/utils/import";
import { Button, ButtonGroup } from "@mui/material";
import { useAppDispatch, useAppSelector } from "@viewer/state/hooks";
import {
  selectBrowserPathwaySelection,
  selectBrowserTaxonSelection,
} from "@viewer/state/slices/browserSelectionSlice";
import { CurrentViewerDocumentActions } from "@viewer/state/slices/currentDocumentSlice";
import { ViewerPanelActions } from "@viewer/state/slices/panelSlice";
import React, { FC } from "react";

type Props = {
  // setIsDrawerOpen: (val: boolean) => void;
};

const useImportModal = () => {
  const { openModal } = useModal();
  const onClickImport = () => {
    openModal("import");
  };
  return { onClickImport };
};

const useLoadButton = () => {
  const dispatch = useAppDispatch();
  const pathwaySelection = useAppSelector(selectBrowserPathwaySelection);
  const taxonSelection = useAppSelector(selectBrowserTaxonSelection);
  const isButtonDisabled = !taxonSelection.length || !pathwaySelection.length;
  const onClickLoad = () => {
    if (isButtonDisabled) return;
    const pathwayId = pathwaySelection[0].id;
    const taxIds = taxonSelection.map((taxon) => taxon.id);
    dispatch(ViewerPanelActions.closeBrowserPanel());
    dispatch(CurrentViewerDocumentActions.setVariantId(pathwayId));
    dispatch(CurrentViewerDocumentActions.setTaxIds(taxIds));
  };

  return { onClickLoad, isButtonDisabled };
};

export const BrowserButtons: FC<Props> = ({}) => {
  const dispatch = useAppDispatch();
  const { onClickLoad, isButtonDisabled } = useLoadButton();
  const { onClickImport } = useImportModal();
  const onClickExample1 = () => {
    dispatch(importData(data4));
    dispatch(ViewerPanelActions.closeBrowserPanel());
  };
  const onClickExample2 = () => {
    dispatch(importData(data5));
    dispatch(ViewerPanelActions.closeBrowserPanel());
  };

  return (
    <ButtonGroup
      sx={{ display: "flex", boxShadow: "none" }}
      variant={"contained"}
      disableElevation
    >
      <Button
        onClick={onClickLoad}
        disabled={isButtonDisabled}
        sx={{ flexGrow: 1 }}
      >
        Plot
      </Button>
      <Button
        onClick={onClickExample1}
        sx={{ fontSize: 11 }}
      >
        Example1
      </Button>
      <Button
        onClick={onClickExample2}
        sx={{ fontSize: 11 }}
      >
        Example2
      </Button>
      <Button
        onClick={onClickImport}
        sx={{ fontSize: 11 }}
      >
        Import (debug only)
      </Button>
    </ButtonGroup>
  );
};
