import { EmotionCacheProvider } from "@core/EmotionCacheProvider";
import type { CommonState } from "@core/state/common";
import { createTheme, ThemeProvider } from "@mui/material/styles";
import type { Store } from "@reduxjs/toolkit";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { FC, PropsWithChildren } from "react";
import { Provider } from "react-redux";

const darkTheme = createTheme({
  palette: {
    mode: "dark",
  },
});
const queryClient = new QueryClient();
type Props = PropsWithChildren<{ store: Store<CommonState> }>;
export const AppProvider: FC<Props> = ({ children, store }) => {
  return (
    <QueryClientProvider client={queryClient}>
      <Provider store={store}>
        <ThemeProvider theme={darkTheme}>
          <EmotionCacheProvider>{children}</EmotionCacheProvider>
        </ThemeProvider>
      </Provider>
    </QueryClientProvider>
  );
};
