import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { LabelKeyActions, selectProteinLabelKey } from "@core/state/slices/app/labelKeySlice";
import { ProteinLabel, ProteinsSelectors } from "@core/state/slices/entities/proteinModelSlice";
import { ReactionsSelectors } from "@core/state/slices/entities/reactionModelsSlice";

export const useProteinPanel = (id: string) => {
  const dispatch = useAppDispatch();
  const currentLabel = useAppSelector(selectProteinLabelKey);
  const protein = useAppSelector((state) => ProteinsSelectors.selectById(state, id));
  const reaction = useAppSelector((state) =>
    ReactionsSelectors.selectById(state, protein?.reactionId ?? "")
  );

  const handleCheckLabel = (value: ProteinLabel) => {
    const next = currentLabel === value ? null : value;
    dispatch(LabelKeyActions.setProteinLabelKey(next));
  };

  return { currentLabel, protein, reaction, handleCheckLabel };
};
