import type { CommonState } from "@core/state/common";
import { createEntityAdapter, createSlice } from "@reduxjs/toolkit";
import { ReactionData } from "@schema/app/ReactionData";
import { nanoid } from "nanoid";

export type ReactionModel = Omit<ReactionData, "references">;
export type ReactionLabel = null | keyof Omit<ReactionModel, "id" | "description" | "synonym">;

const adapter = createEntityAdapter<ReactionModel, string>({
  selectId: (reaction) => reaction.id,
  sortComparer: (a, b) => a.enzymeCode.localeCompare(b.enzymeCode),
});

const slice = createSlice({
  name: "entities/reactions",
  initialState: adapter.getInitialState(),
  reducers: {
    addReaction: adapter.addOne,
    updateReaction: adapter.updateOne,
    upsertReaction: adapter.upsertOne,
    removeReaction: adapter.removeOne,
    addReactions: adapter.addMany,
    updateReactions: adapter.updateMany,
    upsertReactions: adapter.upsertMany,
    removeReactions: adapter.removeMany,
    setReactions: adapter.setAll,
    removeAllReactions: adapter.removeAll,
  },
});

export const reactionsReducer = slice.reducer;
export const ReactionsActions = slice.actions;
export const ReactionsSelectors = adapter.getSelectors<CommonState>(
  (state) => state.entities.reactions
);

export const createNewReaction = (): ReactionModel => ({
  id: nanoid(),
  name: "",
  description: "",
  definition: "",
  enzymeCode: "",
});
