import { MARKER_TYPES } from "@core/canvas/DefaultMarkers";
import { COMPOUND_RADIUS, SUB_COMPOUND_RADIUS } from "@core/canvas/elements/CompoundElement";
import { ConnectionProps } from "@core/canvas/elements/ConnectionElement";
import { generateMarkerId } from "@core/canvas/Markers";
import { getX, getY } from "@core/canvas/utils/setPosition";
import { ConnectionModel } from "@core/state/slices/entities/connectionModelsSlice";
import { NodeModel } from "@core/state/slices/entities/nodeModelsSlice";
import { PathOrientation } from "@schema/app/enums";

export const makeConnectionProps = (
  d: ConnectionModel,
  isSelected: boolean,
  source: NodeModel | undefined,
  target: NodeModel | undefined,
  grid: number
): ConnectionProps => {
  const [ax, ay] = findPos(d, source, target, d.markerSource, grid);
  const [bx, by] = findPos(d, target, source, d.markerTarget, grid);
  const shape = d.shape;
  const orientation = d.orientation;
  const color = d.strokeColor ? d.strokeColor : "#000000";
  const markerStart = d.markerSource ? generateMarkerId(color) : undefined;
  const markerEnd = d.markerTarget ? generateMarkerId(color) : undefined;
  const loopMod = (d.loopMod ?? 1) * grid;
  const strokeDasharray = (() => {
    switch (d.style) {
      case "dashed1":
        return [5, 2];
      case "dotted":
        return [1, 1];
      default:
        return undefined;
    }
  })();
  return {
    ax,
    ay,
    bx,
    by,
    markerEnd,
    markerStart,
    shape,
    orientation,
    isSelected,
    color,
    loopMod,
    strokeDasharray,
  };
};

const findPos = (
  connection: ConnectionModel,
  primary: NodeModel | undefined,
  secondary: NodeModel | undefined,
  hasMarker: boolean,
  grid: number
): [number, number] => {
  if (!primary || !secondary) return [0, 0];
  const modX = hasMarker ? getModX(connection, primary, secondary) : 0;
  const modY = hasMarker ? getModY(connection, primary, secondary) : 0;
  //
  return [getX(primary.x, grid, modX), getY(primary.y, grid, modY)];
};

const getFinalOrientation = (connection: ConnectionModel): PathOrientation => {
  switch (connection.shape) {
    case "rightAngle":
    case "loop":
      return connection.orientation === "vertical" ? "horizontal" : "vertical";
    default:
      return connection.orientation;
  }
};
const getModX = (connection: ConnectionModel, primary: NodeModel, secondary: NodeModel): number => {
  if (getFinalOrientation(connection) === "vertical") return 0;
  const loopModPos: "left" | "right" = (connection.loopMod ?? 1) > 0 ? "right" : "left";
  const direction: "rightToLeft" | "leftToRight" = (() => {
    if (connection.shape === "loop") {
      return loopModPos === "left" ? "leftToRight" : "rightToLeft";
    } else {
      return primary.x < secondary.x ? "rightToLeft" : "leftToRight";
    }
  })();
  const R = getNodeRadius(primary);
  return R * (direction === "leftToRight" ? 1 : -1);
};

const getModY = (connection: ConnectionModel, primary: NodeModel, secondary: NodeModel): number => {
  if (getFinalOrientation(connection) === "horizontal") return 0;
  const loopModPos: "top" | "bottom" = (connection.loopMod ?? 1) > 0 ? "bottom" : "top";
  const direction: "bottomToTop" | "topToBottom" = (() => {
    if (connection.shape === "loop") {
      return loopModPos === "top" ? "topToBottom" : "bottomToTop";
    } else {
      return primary.y < secondary.y ? "bottomToTop" : "topToBottom";
    }
  })();
  const R = getNodeRadius(primary);
  return direction === "bottomToTop" ? (R + 15) * -1 : R;
};

const getNodeRadius = (node: NodeModel): number => {
  const EX = 5;
  switch (node.entityType) {
    case "reaction":
      return 5 + EX;
    case "compound":
      return COMPOUND_RADIUS + EX;
    case "subCompound":
      return SUB_COMPOUND_RADIUS + EX;
    default:
      return 0;
  }
};
