const taxonomyTagId = "taxonomy";

export const importDataFromJson =
  (str: string): CommonThunk =>
  (dispatch) => {
    const data = parseJson(str);
    z.safeParseAsync(appDataSchema, data)
      .then((result) => {
        if (result.success) {
          dispatch(importData(result.data));
        } else {
          dispatch(ErrorLogActions.addError("Parse error. Check the console for details."));
          console.warn("Error parsing JSON:");
          console.warn(result.error.message);
        }
      })
      .catch((error: unknown) => {
        dispatch(ErrorLogActions.addError("Import failed. Check the console for details."));
        console.warn("Error importing JSON:", error);
      });
  };

type LayoutDataWithId = Omit<LayoutData, "id"> & { id: string };

export const importData =
  (data: AppData, merge: boolean = false): CommonThunk =>
  (dispatch) => {
    // console.log("importData", data);
    if (!merge) dispatch(clearData());
    //
    const tempLayoutData: LayoutDataWithId[] = data.layouts.map((layout) => ({
      ...layout,
      id: layout.id || nanoid(),
    }));

    dispatch(DocumentsActions.upsertDocument(extractDocument(data)));
    //
    dispatch(LayoutsActions.upsertLayouts(extractLayouts(tempLayoutData, data.document.id)));
    dispatch(LayoutTagActions.upsertLayoutTags(extractLayoutTags(data.layoutTags)));
    dispatch(
      LayoutTagValueActions.upsertLayoutTagValues(
        extractLayoutTagValues(
          data.layoutTags,
          data.document.taxId,
          data.document.organism ?? data.document.taxId
        )
      )
    );
    dispatch(
      LayoutTagRelationsActions.upsertLayoutTagRelations(
        extractLayoutTagRelations(tempLayoutData, data.document.taxId)
      )
    );
    //
    dispatch(ConnectionsActions.upsertConnections(extractConnections(tempLayoutData)));
    dispatch(NodesActions.upsertNodes(extractNodes(tempLayoutData)));
    //
    dispatch(CompoundsActions.upsertCompounds(extractCompounds(data.entities.compounds)));
    dispatch(ReactionsActions.upsertReactions(extractReactions(data.entities.reactions)));
    dispatch(ProteinsActions.upsertProteins(extractProteins(data.entities.proteins)));
    //
    dispatch(ReferencesActions.upsertReferences(extractReferences(data, tempLayoutData)));
    //
    // dispatch(AppActions.resetAppState());
  };
/**
 * for storybook testing
 * @param data
 * @todo: hide from other modules
 */
export const convertDataToState = (data: AppData): AppDataState => {
  const tempLayoutData: LayoutDataWithId[] = data.layouts.map((layout) => ({
    ...layout,
    id: layout.id || nanoid(),
  }));

  return {
    documents: [],
    layouts: extractLayouts(tempLayoutData, data.document.id),
    layoutTags: extractLayoutTags(data.layoutTags),
    layoutTagValues: extractLayoutTagValues(
      data.layoutTags,
      data.document.taxId,
      data.document.organism ?? data.document.taxId
    ),
    layoutTagRelations: extractLayoutTagRelations(tempLayoutData, data.document.taxId),
    nodes: extractNodes(tempLayoutData),
    connections: extractConnections(tempLayoutData),
    references: extractReferences(data, tempLayoutData),
    reactions: extractReactions(data.entities.reactions),
    compounds: extractCompounds(data.entities.compounds),
    proteins: extractProteins(data.entities.proteins),
  };
};

const extractDocument = (data: AppData): DocumentModel => {
  const { references, ...rest } = data.document;
  const documentId = data.document.id;
  return { ...rest, id: documentId, visible: true };
};
const extractLayouts = (layouts: LayoutDataWithId[], documentId: string): LayoutModel[] => {
  return layouts.map((layout) => {
    const { references, nodes, connections, tags, ...rest } = layout;
    return { ...rest, documentId };
  });
};
const extractLayoutTags = (data: LayoutTagData[]): LayoutTagModel[] => {
  const taxonomy: LayoutTagModel = {
    id: taxonomyTagId,
    label: "Taxonomy",
    selectionType: "multiple",
  };
  return [
    taxonomy,
    ...data.map((tag) => {
      const { values, ...rest } = tag;
      return { ...rest };
    }),
  ];
};
const extractLayoutTagValues = (
  data: LayoutTagData[],
  taxId: string,
  taxLabel: string
): LayoutTagValueModel[] => {
  const taxonomy: LayoutTagValueModel = {
    id: `${taxonomyTagId}${TAG_VALUE_DIVIDER}${taxId}`,
    tagId: taxonomyTagId,
    key: taxId,
    label: taxLabel,
  };
  return [
    taxonomy,
    ...data
      .map((tag) =>
        tag.values.map((value) => {
          return {
            ...value,
            id: `${tag.id}${TAG_VALUE_DIVIDER}${value.key}`,
            tagId: tag.id,
          };
        })
      )
      .flat(),
  ];
};
const extractLayoutTagRelations = (
  layouts: LayoutDataWithId[],
  taxId: string
): LayoutTagRelationModel[] => {
  return layouts
    .map((layout) => {
      const taxonomy: LayoutTagRelationModel = {
        id: nanoid(),
        layoutId: layout.id,
        tagId: taxonomyTagId,
        tagValue: taxId,
      };

      return [
        taxonomy,
        ...Object.entries(layout.tags).map(([tagId, tagValue]) => ({
          id: nanoid(),
          layoutId: layout.id,
          tagId,
          tagValue,
        })),
      ];
    })
    .flat();
};

const extractCompounds = (compounds: CompoundData[]): CompoundModel[] => {
  return compounds.map((compound) => {
    const { references, ...rest } = compound;
    return rest;
  });
};
const extractReactions = (reactions: ReactionData[]): ReactionModel[] => {
  return reactions.map((reaction) => {
    const { references, ...rest } = reaction;
    return rest;
  });
};
const extractProteins = (proteins: ProteinData[]): ProteinModel[] => {
  const result: ProteinModel[] = [];
  const parseItem = (item: ProteinData) => {
    const { references, oneOf, allOf, ...rest } = item;
    const model: ProteinModel = { ...rest };
    result.push(model);
    if (oneOf) {
      oneOf.forEach(parseItem);
      model.oneOf = oneOf.map((p) => p.id);
    }
    if (allOf) {
      allOf.forEach(parseItem);
      model.allOf = allOf.map((p) => p.id);
    }
  };
  proteins.forEach(parseItem);
  return result;
};

const extractNodes = (layouts: LayoutDataWithId[]): NodeModel[] => {
  return layouts
    .map((layout) => {
      return layout.nodes.map((node) => {
        return {
          ...node,
          id: `${layout.id}:${node.id}`,
          layoutId: layout.id,
        };
      });
    })
    .flat();
};
const extractConnections = (layouts: LayoutDataWithId[]): ConnectionModel[] => {
  return layouts
    .map((layout) => {
      const layoutId = layout.id;
      return layout.connections.map((connection) => ({
        ...connection,
        id: `${layoutId}:${connection.id}`,
        source: `${layoutId}:${connection.source}`,
        target: `${layoutId}:${connection.target}`,
        layoutId,
      }));
    })
    .flat();
};

const extractReferences = (data: AppData, layouts: LayoutDataWithId[]): ReferenceModel[] => {
  const documentId: string = data.document.id;
  const proteinRefs: ReferenceModel[] = [];
  const parseProteinRefs = (item: ProteinData) => {
    proteinRefs.push(
      ...(item.references ?? []).map((ref) => ({ ...ref, id: nanoid(), parentId: item.id }))
    );
    if (item.oneOf) item.oneOf.forEach(parseProteinRefs);
    if (item.allOf) item.allOf.forEach(parseProteinRefs);
  };
  data.entities.proteins.forEach(parseProteinRefs);
  const documentRefs: ReferenceModel[] = [];
  (data.document.references ?? []).forEach((ref) => {
    documentRefs.push({ ...ref, id: nanoid(), parentId: documentId });
  });
  const compoundRefs: ReferenceModel[] = data.entities.compounds
    .map((item) =>
      (item.references ?? []).map((ref) => ({ ...ref, id: nanoid(), parentId: item.id }))
    )
    .flat();
  const reactionRefs: ReferenceModel[] = data.entities.reactions
    .map((item) =>
      (item.references ?? []).map((ref) => ({ ...ref, id: nanoid(), parentId: item.id }))
    )
    .flat();
  const layoutRefs: ReferenceModel[] = layouts
    .map((layout) =>
      (layout.references ?? []).map((ref) => ({ ...ref, id: nanoid(), parentId: layout.id }))
    )
    .flat();

  return [...layoutRefs, ...reactionRefs, ...compoundRefs, ...proteinRefs, ...documentRefs];
};

export const getEmptyData = (title: string = "New document", description: string = ""): AppData => {
  return {
    document: { title, description, references: [], taxId: "", organism: "", id: "" },
    layouts: [{ ...createNewLayoutEntity(), references: [], nodes: [], connections: [], tags: {} }],
    entities: {
      proteins: [],
      reactions: [],
      compounds: [],
    },
    layoutTags: [],
    meta: {
      ver: currentVer,
    },
  };
};

const parseJson = (str: string): AppData => {
  try {
    const data = JSON.parse(str);
    return data;
  } catch (e) {
    console.warn("Error parsing JSON");
    return getEmptyData("Error", "Error parsing JSON");
  }
};

