import { ColorArg } from "@core/types";
import { colord } from "colord";
import React, { FC, useMemo } from "react";

export type MarkerType = "arrow" | "circle" | "diamond" | "square" | "triangle";
type Props = {
  id: string;
  type?: MarkerType;
  size?: number;
  fillColor?: ColorArg;
  outlineColor?: ColorArg;
  outlineWidth?: number;
};
export type MarkerProps = Omit<Props, "setId">;

export const Marker: FC<Props> = ({
  id,
  type = "arrow",
  size = 12,
  fillColor = "#000000",
  outlineColor,
  outlineWidth,
}) => {
  return (
    <defs>
      <marker
        id={id}
        viewBox={`0 0 ${size} ${size}`}
        refX={size}
        refY={size / 2}
        markerUnits="strokeWidth"
        markerWidth={size}
        markerHeight={size}
        orient="auto-start-reverse"
      >
        <MarkerShape
          size={size}
          fillColor={fillColor}
          outlineColor={outlineColor}
          type={type}
          outlineWidth={outlineWidth}
        />
      </marker>
    </defs>
  );
};

const MarkerShape: FC<{
  type: MarkerType;
  size: number;
  fillColor: ColorArg;
  outlineColor?: ColorArg;
  outlineWidth?: number;
}> = ({ type, size, fillColor, outlineColor, outlineWidth }) => {
  const stroke = useMemo(() => {
    if (outlineColor) {
      return colord(outlineColor).toHex();
    } else if (!outlineColor && outlineWidth && outlineWidth >= 0) {
      return colord(fillColor).toHex();
    }
    return "";
  }, [fillColor, outlineColor, outlineWidth]);
  const strokeWidth = useMemo(() => {
    if (!!outlineWidth && outlineWidth >= 0) {
      return outlineWidth.toString();
    } else if (outlineColor && !outlineWidth) {
      return "1";
    }
    return "";
  }, [outlineWidth, outlineColor]);

  switch (type) {
    case "arrow":
      return (
        <path
          d={makeArrowMarkerPath(size)}
          fill={fillColor && colord(fillColor).toHex()}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      );
    case "circle":
      return (
        <circle
          cx={size / 2}
          cy={size / 2}
          r={size / 2 - (strokeWidth ? Number(strokeWidth) / 2 : 0)}
          fill={fillColor && colord(fillColor).toHex()}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      );
    case "diamond":
      return (
        <path
          d={makeDiamondMarkerPath(size)}
          fill={fillColor && colord(fillColor).toHex()}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      );
    case "square":
      return (
        <rect
          x={0}
          y={0}
          width={size}
          height={size}
          fill={fillColor && colord(fillColor).toHex()}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      );
    case "triangle":
      return (
        <path
          d={makeTriangleMarkerPath(size)}
          fill={fillColor && colord(fillColor).toHex()}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      );
    default:
      return (
        <path
          d={makeArrowMarkerPath(size)}
          fill={fillColor && colord(fillColor).toHex()}
          stroke={stroke}
          strokeWidth={strokeWidth}
        />
      );
  }
};

const makeArrowMarkerPath = (size: number) => {
  return `M 0 0 L ${size} ${size / 2} L 0 ${size} L ${size / 3} ${size / 2} Z`;
};
const makeDiamondMarkerPath = (size: number) => {
  return `M 0 ${size / 2} L ${size / 2} 0 L ${size} ${size / 2} L ${size / 2} ${size} Z`;
};
const makeTriangleMarkerPath = (size: number) => {
  return `M 0 0 L ${size} ${size / 2} L 0 ${size}`;
};
