import Box from "@mui/material/Box";
import MuiCheckbox, { CheckboxProps } from "@mui/material/Checkbox";
import { blue, grey } from "@mui/material/colors";
import { FC } from "react";

type Props = {} & CheckboxProps;
export const Checkbox: FC<Props> = (props) => {
  const s = props.size === "small" ? "16px" : "20px";
  return (
    <MuiCheckbox
      sx={{
        padding: 0,
        width: s,
        height: s,
      }}
      icon={<CheckBoxIcon />}
      checkedIcon={<CheckBoxIcon checked />}
      disableRipple
      {...props}
    />
  );
};

const CheckBoxIcon: FC<{
  checked?: boolean;
}> = ({ checked }) => {
  return (
    <Box
      sx={{
        width: "100%",
        height: "100%",
        borderRadius: 1,
        border: `1px solid ${blue[800]}`,
        backgroundColor: "#000",
        color: grey[400],
      }}
    >
      {checked && (
        <svg
          focusable="false"
          aria-hidden="true"
          viewBox="0 0 24 24"
          fill="currentColor"
        >
          <path d="M9 16.17 5.53 12.7a.9959.9959 0 0 0-1.41 0c-.39.39-.39 1.02 0 1.41l4.18 4.18c.39.39 1.02.39 1.41 0L20.29 7.71c.39-.39.39-1.02 0-1.41a.9959.9959 0 0 0-1.41 0L9 16.17z"></path>
        </svg>
      )}
    </Box>
  );
};
