import { Accordion, AccordionDetails, AccordionSummary } from "@core/components/mui/Accordion";
import { useAppSelector } from "@core/state/hooks";
import { ProteinModel, ProteinsSelectors } from "@core/state/slices/entities/proteinModelSlice";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import Stack from "@mui/material/Stack";
import { useProteinPanel } from "@viewer/hooks/useProteinPanel";
import { ProteinPane } from "@viewer/propertyPanel/pane/ProteinPane";
import { FieldSet } from "@viewer/propertyPanel/sub/FieldSet";
import React, { FC, useMemo } from "react";

type Props = { id: string };

export const AndProteinPane: FC<Props> = ({ id }) => {
  const { currentLabel, protein, reaction, handleCheckLabel } = useProteinPanel(id);
  const allOf = useAllOf(protein);
  if (allOf.length === 0) return null;
  return (
    <Stack sx={{ gap: 1.5 }}>
      <FieldSet
        title={"Name"}
        checkBoxProps={{
          checked: currentLabel === "name",
          onClick: () => handleCheckLabel("name"),
        }}
      >
        {protein.name}
      </FieldSet>
      <FieldSet
        title={"Reaction name"}
        checkBoxProps={{
          checked: currentLabel === "reactionName",
          onClick: () => handleCheckLabel("reactionName"),
        }}
      >
        {reaction?.name}
      </FieldSet>
      <FieldSet
        title={"Enzyme code"}
        checkBoxProps={{
          checked: currentLabel === "enzymeCode",
          onClick: () => handleCheckLabel("enzymeCode"),
        }}
      >
        {reaction?.enzymeCode}
      </FieldSet>

      <FieldSet title={"Components"}>
        {allOf.map((p) => (
          <Accordion key={p.id}>
            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
              {p.geneName || p.name || (p.oneOf && "One of ") || (p.allOf && "All of ")}
            </AccordionSummary>
            <AccordionDetails>
              <ProteinPane
                id={p.id}
                parentId={id}
              />
            </AccordionDetails>
          </Accordion>
        ))}
      </FieldSet>
    </Stack>
  );
};

const useAllOf = (protein: ProteinModel) => {
  const allProteins = useAppSelector(ProteinsSelectors.selectAll);
  const allOf = useMemo(() => {
    return allProteins.filter((p) => protein?.allOf?.includes(p.id) ?? false);
  }, [protein, allProteins]);
  return allOf;
};
