import type { CommonState } from "@core/state/common";
import { LayoutTagSelectors } from "@core/state/slices/entities/layoutTagModelSlice";
import { LayoutTagRelationSelectors } from "@core/state/slices/entities/layoutTagRelationsSlice";
import {
  LayoutTagValueSelectors,
  TAG_VALUE_DIVIDER,
} from "@core/state/slices/entities/layoutTagValueModelSlice";
import { createSelector } from "@reduxjs/toolkit";

export const selectLayoutTags = createSelector(
  [
    LayoutTagSelectors.selectAll,
    LayoutTagValueSelectors.selectAll,
    LayoutTagRelationSelectors.selectAll,
    (state: CommonState, layoutId: string) => layoutId,
  ],
  (tags, values, relations, layoutId) => {
    return relations
      .filter((relation) => relation.layoutId === layoutId)
      .map((relation) => {
        // console.log(relation);
        const tag = tags.find((tag) => tag.id === relation.tagId);
        if (!tag) {
          console.warn("Tag not found with", relation);
        }
        const value = values.find(
          (value) => value.id === `${tag?.id}${TAG_VALUE_DIVIDER}${relation.tagValue}`
        );
        if (!value) {
          console.warn("Value not found with", relation);
        }

        return { tag, value };
      })
      .filter(({ tag, value }) => tag !== undefined && value !== undefined);
  }
);
