import { useAppSelector } from "@core/state/hooks";
import {
  ReferenceModel,
  ReferencesSelectors,
} from "@core/state/slices/entities/referenceModelsSlice";
import Link from "@mui/material/Link";
import List from "@mui/material/List";
import ListItem from "@mui/material/ListItem";
import Tooltip from "@mui/material/Tooltip";
import { FieldSet } from "@viewer/propertyPanel/sub/FieldSet";
import React, { FC } from "react";

type Props = { parentId: string };

export const ReferenceList: FC<Props> = ({ parentId }) => {
  const references: ReferenceModel[] = useAppSelector((state) =>
    ReferencesSelectors.selectReferencesByParentId(state, parentId)
  );
  if (references.length == 0) return <></>;

  return (
    <FieldSet title={"References"}>
      <List>
        {references.map((r) => (
          <ReferenceListItem
            key={r.id}
            label={r.label}
            url={r.url}
          />
        ))}
      </List>
    </FieldSet>
  );
};

const ReferenceListItem: FC<{
  label: string;
  url: string;
}> = ({ label, url }) => {
  return (
    <ListItem sx={{ paddingInline: 0 }}>
      <Tooltip
        title={label}
        placement={"bottom-start"}
        enterNextDelay={500}
        enterDelay={500}
      >
        <Link
          href={url}
          color="inherit"
          underline="none"
          target="_blank"
          rel="noopener"
          sx={{
            display: "block",
            width: "100%",
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
            marginInline: 0,
            lineHeight: 1.5,
          }}
        >
          🔗 {label}
        </Link>
      </Tooltip>
    </ListItem>
  );
};
