import { Checkbox } from "@core/components/mui/Checkbox";
import { FolderIcon } from "@core/icons/FolderIcon";
import { FolderOpenIcon } from "@core/icons/FolderOpenIcon";
import { SmallCircleIcon } from "@core/icons/SmallCircleIcon";
import { DocumentTreeData } from "@core/types";
import { capitalizeFirstLetter } from "@core/utils/capitalizeFirstLetter";
import { useTheme, Tooltip, Box, Typography } from "@mui/material";
import { styled } from "@mui/material/styles";
import { treeItemClasses, TreeItemProps, useTreeItemUtils } from "@mui/x-tree-view";
import { TreeItem } from "@mui/x-tree-view/TreeItem";
import React from "react";

type StyledTreeItemProps = TreeItemProps & {
  data: DocumentTreeData;
  selections: TreeItemLabel[];
  setSelections: (item: TreeItemLabel) => void;
};
export type TreeItemLabel = {
  id: string;
  label: string;
};

export const StyledTreeItem = React.forwardRef(function StyledTreeItem(
  props: StyledTreeItemProps,
  ref: React.Ref<HTMLLIElement>
) {
  const { data, selections, setSelections, ...other } = props;
  const {
    status: { expanded },
  } = useTreeItemUtils({ itemId: data.id, children: other.children });
  const theme = useTheme();
  const isLastItem = !data.children?.length;
  const Icon = isLastItem ? SmallCircleIcon : expanded ? FolderOpenIcon : FolderIcon;
  const textColor = data.num_of_data ? theme.palette.text.primary : theme.palette.text.secondary;
  const iconAlpha = data.num_of_data ? 1 : 0.3;
  const isSelected = selections.some((item) => item.id === data.id);

  return (
    <StyledTreeItemRoot
      label={
        <Tooltip
          title={data.label}
          placement={"bottom-start"}
          slotProps={{ popper: { disablePortal: true } }}
          enterNextDelay={500}
          enterDelay={500}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: "4px",
              // justifyContent: "space-between",
            }}
          >
            <Box
              sx={{
                display: "flex",
                flexGrow: 1,
                overflow: "hidden",
                alignItems: "center",
              }}
            >
              <Box
                component={Icon}
                sx={{ height: "14px", opacity: iconAlpha, position: "relative", top: "-1px" }}
              />
              <Typography
                sx={{
                  flexGrow: 1,
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  color: textColor,
                  fontSize: "12px",
                }}
              >
                {capitalizeFirstLetter(data.label)}
              </Typography>
            </Box>
            <Box sx={{ display: "flex", alignItems: "center" }}>
              {!isLastItem && (
                <Typography sx={{ color: textColor, fontSize: "12px" }}>
                  {data.num_of_data}
                </Typography>
              )}
              {data.selectable && (
                <Checkbox
                  size="small"
                  checked={isSelected}
                  onClick={() => {
                    setSelections({
                      id: data.id,
                      label: data.label,
                    });
                  }}
                />
              )}
            </Box>
          </Box>
        </Tooltip>
      }
      {...other}
      ref={ref}
    />
  );
});

const StyledTreeItemRoot = styled(TreeItem)(({ theme }) => ({
  [`& .${treeItemClasses.content}`]: {
    borderRadius: "4px",
    height: "24px",
    paddingLeft: "0",
    marginLeft: "2px",
  },
  [`& .${treeItemClasses.label}`]: {
    paddingLeft: "0",
  },
  [`& .${treeItemClasses.content} .${treeItemClasses.iconContainer}`]: {
    display: "none",
  },
  [`& .${treeItemClasses.groupTransition}`]: {
    marginLeft: "13px",
    borderLeft: `1px dashed ${theme.palette.divider}`,
  },
})) as unknown as typeof TreeItem;
