import { extendZod } from "@schema/extendZod";
import z from "zod";

extendZod();

export const reactionDataSchema = z
  .object({
    id: z.string(),
    name: z.string(),
    synonym: z.string().optional(),
    description: z.string().optional(),
    definition: z.string(),
    enzymeCode: z.string(),
    references: z.array(z.any()).optional(),
  })
  .openapi("ReactionData");

export type ReactionData = z.infer<typeof reactionDataSchema>;
