import { Sheet } from "@core/components/mui/Sheet";
import { useAppDispatch, useAppSelector } from "@core/state/hooks";
import { LabelKeyActions, selectReactionLabelKey } from "@core/state/slices/app/labelKeySlice";
import { ReactionLabel, ReactionsSelectors } from "@core/state/slices/entities/reactionModelsSlice";
import { FieldSet } from "@viewer/propertyPanel/sub/FieldSet";
import { ReferenceList } from "@viewer/propertyPanel/sub/ReferenceList";
import React, { FC } from "react";

type Props = {
  id: string;
};

export const ReactionPane: FC<Props> = ({ id }) => {
  const dispatch = useAppDispatch();
  const reaction = useAppSelector((state) => ReactionsSelectors.selectById(state, id));
  const currentLabel = useAppSelector(selectReactionLabelKey);
  //
  if (!reaction) return <></>;
  const onCheckLabel = (value: ReactionLabel) => {
    const next = currentLabel === value ? null : value;
    dispatch(LabelKeyActions.setReactionLabelKey(next));
  };

  return (
    <Sheet
      sx={{ maxHeight: "max-content", p: 2, display: "flex", flexDirection: "column", gap: 2 }}
    >
      <FieldSet
        title={"Name"}
        checkBoxProps={{
          checked: currentLabel === "name",
          onClick: () => onCheckLabel("name"),
        }}
      >
        {reaction.name}
      </FieldSet>

      <FieldSet
        title={"Enzyme code"}
        checkBoxProps={{
          checked: currentLabel === "enzymeCode",
          onClick: () => onCheckLabel("enzymeCode"),
        }}
      >
        {reaction.enzymeCode}
      </FieldSet>
      <FieldSet
        title={"Definition"}
        checkBoxProps={{
          checked: currentLabel === "definition",
          onClick: () => onCheckLabel("definition"),
        }}
      >
        {reaction.definition}
      </FieldSet>
      <FieldSet title={"Description"}>{reaction.description}</FieldSet>

      <ReferenceList parentId={id} />
    </Sheet>
  );
};
