import type { CommonThunk } from "@core/state/hooks";
import { CompoundsActions } from "@core/state/slices/entities/compoundModelsSlice";
import { ConnectionsActions } from "@core/state/slices/entities/connectionModelsSlice";
import { DocumentsActions } from "@core/state/slices/entities/documentModelsSlice";
import { LayoutsActions } from "@core/state/slices/entities/layoutModelsSlice";
import { LayoutTagActions } from "@core/state/slices/entities/layoutTagModelSlice";
import { LayoutTagRelationsActions } from "@core/state/slices/entities/layoutTagRelationsSlice";
import { LayoutTagValueActions } from "@core/state/slices/entities/layoutTagValueModelSlice";
import { NodesActions } from "@core/state/slices/entities/nodeModelsSlice";
import { ProteinsActions } from "@core/state/slices/entities/proteinModelSlice";
import { ReactionsActions } from "@core/state/slices/entities/reactionModelsSlice";
import { ReferencesActions } from "@core/state/slices/entities/referenceModelsSlice";

export const clearData = (): CommonThunk => (dispatch) => {
  dispatch(DocumentsActions.removeAllDocuments());
  dispatch(LayoutTagRelationsActions.removeAllLayoutTagRelations());
  dispatch(LayoutTagActions.removeAllLayoutTags());
  dispatch(LayoutTagValueActions.removeAllLayoutTagValues());
  dispatch(LayoutsActions.removeAllLayouts());
  dispatch(NodesActions.removeAllNodes());
  dispatch(ConnectionsActions.removeAllConnections());
  dispatch(ReferencesActions.removeAllReferences());
  dispatch(ReactionsActions.removeAllReactions());
  dispatch(CompoundsActions.removeAllCompounds());
  dispatch(ProteinsActions.removeAllProteins());
  // dispatch(AppActions.resetAppState());
};
