import { Marker } from "@core/canvas/atoms/Marker";
import { useAppSelector } from "@core/state/hooks";
import { ConnectionsSelectors } from "@core/state/slices/entities/connectionModelsSlice";
import { FC } from "react";

export const Markers: FC = () => {
  const markerColors = useAppSelector(ConnectionsSelectors.selectConnectionColors);
  return (
    <g>
      {markerColors.map((c) => {
        const id = generateMarkerId(c);
        return (
          <Marker
            key={id}
            id={id}
            type={"arrow"}
            fillColor={c}
          />
        );
      })}
    </g>
  );
};

export const generateMarkerId = (color: string, type: "arrow" | "circle" = "arrow") => {
  return `marker-${type}-${color.replace("#", "").toLowerCase()}`;
};
