import type { CommonState } from "@core/state/common";
import { CompoundLabel } from "@core/state/slices/entities/compoundModelsSlice";
import { DocumentLabel } from "@core/state/slices/entities/documentModelsSlice";
import { ProteinLabel } from "@core/state/slices/entities/proteinModelSlice";
import { ReactionLabel } from "@core/state/slices/entities/reactionModelsSlice";
import { createSelector, createSlice } from "@reduxjs/toolkit";

type State = {
  compound: CompoundLabel;
  subCompound: CompoundLabel;
  reaction: ReactionLabel;
  document: DocumentLabel;
  protein: ProteinLabel;
};

const initialState: State = {
  document: "title",
  compound: "name",
  subCompound: "name",
  reaction: "name",
  protein: "name",
};

const slice = createSlice({
  name: "app/labelKey",
  initialState,
  reducers: {
    setCompoundLabelKey(state, action: { payload: CompoundLabel }) {
      state.compound = action.payload;
    },
    setSubCompoundLabelKey(state, action: { payload: CompoundLabel }) {
      state.subCompound = action.payload;
    },
    setReactionLabelKey(state, action: { payload: ReactionLabel }) {
      state.reaction = action.payload;
    },
    setDocumentLabelKey(state, action: { payload: DocumentLabel }) {
      state.document = action.payload;
    },
    setProteinLabelKey(state, action: { payload: ProteinLabel }) {
      state.protein = action.payload;
    },
  },
});

export const labelKeyReducer = slice.reducer;
export const LabelKeyActions = slice.actions;

const selectState = (state: CommonState) => state.app.labelKey;
export const selectCompoundLabelKey = createSelector(selectState, (s) => s.compound);
export const selectSubCompoundLabelKey = createSelector(selectState, (s) => s.subCompound);
export const selectReactionLabelKey = createSelector(selectState, (s) => s.reaction);
export const selectDocumentLabelKey = createSelector(selectState, (s) => s.document);
export const selectProteinLabelKey = createSelector(selectState, (s) => s.protein);
