import { createSelector, createSlice } from "@reduxjs/toolkit";
import type { RootState } from "@viewer/state/store";

type State = {
  isBrowserPanelOpen: boolean;
  isPropertyPanelOpen: boolean;
};

const initialState: State = {
  isBrowserPanelOpen: true,
  isPropertyPanelOpen: true,
};

const slice = createSlice({
  name: "viewer/panels",
  initialState,
  reducers: {
    openBrowserPanel(state) {
      state.isBrowserPanelOpen = true;
    },
    closeBrowserPanel(state) {
      state.isBrowserPanelOpen = false;
    },
    toggleBrowserPanel(state) {
      state.isBrowserPanelOpen = !state.isBrowserPanelOpen;
    },
    openPropertyPanel(state) {
      state.isPropertyPanelOpen = true;
    },
    closePropertyPanel(state) {
      state.isPropertyPanelOpen = false;
    },
    togglePropertyPanel(state) {
      state.isPropertyPanelOpen = !state.isPropertyPanelOpen;
    },
  },
});

export const ViewerPanelActions = slice.actions;
export const viewerPanelReducer = slice.reducer;

const selectState = (state: RootState) => state.viewer.panel;
export const selectIsBrowserPanelOpen = createSelector(selectState, (s) => s.isBrowserPanelOpen);
export const selectIsPropertyPanelOpen = createSelector(selectState, (s) => s.isPropertyPanelOpen);
